import { useState, useEffect } from 'react';
import { X, ChevronRight, ChevronLeft, CheckCircle } from 'lucide-react';
import { useAuthStore } from '@/stores/authStore';

const ONBOARDING_KEY = 'kabrak_onboarding_done';

const getSlides = (plan: string, mode: string, language: string) => {
  const fr = language === 'fr';

  const baseSlides = [
    {
      icon: '≡ƒÅ¬',
      title: fr ? 'Bienvenue sur KABRAK Store' : 'Welcome to KABRAK Store',
      description: fr
        ? 'G├¿re ta boutique, ton stock, tes commandes et tes factures en un seul endroit.'
        : 'Manage your store, stock, orders and invoices in one place.',
    },
  ];

  if (mode === 'PRODUCT') {
    baseSlides.push(
      {
        icon: '≡ƒôª',
        title: fr ? 'Commence par les produits' : 'Start with products',
        description: fr
          ? 'Ajoute tes produits avec leurs prix et stock. C\'est la base de ton catalogue.'
          : 'Add your products with prices and stock. This is the base of your catalog.',
      },
      {
        icon: '≡ƒæÑ',
        title: fr ? 'Enregistre tes clients' : 'Register your clients',
        description: fr
          ? 'Cr├⌐e tes clients pour suivre leur historique d\'achats et les fid├⌐liser.'
          : 'Create your clients to track their purchase history and build loyalty.',
      },
      {
        icon: '≡ƒ¢Æ',
        title: fr ? 'Vends facilement' : 'Sell easily',
        description: fr
          ? 'Cr├⌐e des commandes en quelques clics. Le stock se met ├á jour automatiquement.'
          : 'Create orders in a few clicks. Stock updates automatically.',
      },
      {
        icon: '≡ƒôä',
        title: fr ? 'Factures professionnelles' : 'Professional invoices',
        description: fr
          ? 'Envoie des factures par WhatsApp avec ton logo. Tes clients seront impressionn├⌐s.'
          : 'Send invoices via WhatsApp with your logo. Your clients will be impressed.',
      }
    );

    if (plan === 'SHOP' || plan === 'BUSINESS') {
      baseSlides.push(
        {
          icon: '≡ƒÆ╗',
          title: fr ? 'Caisse POS' : 'POS Cash Register',
          description: fr
            ? 'Utilise la caisse pour les ventes en magasin. Scan produit, monnaie automatique.'
            : 'Use the cash register for in-store sales. Scan product, automatic change.',
        },
        {
          icon: '≡ƒôè',
          title: fr ? 'Rapports d├⌐taill├⌐s' : 'Detailed reports',
          description: fr
            ? 'Analyse tes ventes, b├⌐n├⌐fices, top clients et produits. Exporte en Excel.'
            : 'Analyze your sales, profits, top clients and products. Export to Excel.',
        }
      );
    }

    if (plan === 'BUSINESS') {
      baseSlides.push(
        {
          icon: '≡ƒÅó',
          title: fr ? 'Multi-boutiques' : 'Multi-stores',
          description: fr
            ? 'G├¿re plusieurs points de vente depuis un seul compte. Rapports par boutique.'
            : 'Manage multiple points of sale from one account. Reports by store.',
        },
        {
          icon: '≡ƒñû',
          title: fr ? 'Rapports IA' : 'AI Reports',
          description: fr
            ? 'Analyse intelligente avec recommandations personnalis├⌐es. Pose des questions en langage naturel.'
            : 'Intelligent analysis with personalized recommendations. Ask questions in natural language.',
        }
      );
    }
  } else {
    // SERVICE mode
    baseSlides.push(
      {
        icon: '≡ƒôï',
        title: fr ? 'Cr├⌐e tes services' : 'Create your services',
        description: fr
          ? 'D├⌐finis tes offres de services avec prix, dur├⌐e et type de facturation.'
          : 'Define your service offerings with price, duration and billing type.',
      },
      {
        icon: '≡ƒôü',
        title: fr ? 'G├¿re tes projets' : 'Manage your projects',
        description: fr
          ? 'Cr├⌐e des projets clients avec budget, jalons et suivi de paiement.'
          : 'Create client projects with budget, milestones and payment tracking.',
      },
      {
        icon: '≡ƒôä',
        title: fr ? 'Facturation r├⌐currente' : 'Recurring billing',
        description: fr
          ? 'Automatise les factures pour tes abonnements mensuels ou trimestriels.'
          : 'Automate invoices for your monthly or quarterly subscriptions.',
      },
      {
        icon: '≡ƒæÑ',
        title: fr ? 'Enregistre tes clients' : 'Register your clients',
        description: fr
          ? 'Cr├⌐e tes clients pour suivre leur historique d\'achats et les fid├⌐liser.'
          : 'Create your clients to track their purchase history and build loyalty.',
      }
    );
  }

  return baseSlides;
};

export function Onboarding() {
  const { language, tenant } = useAuthStore();
  const fr = language === 'fr';
  const plan = tenant?.plan || 'STORE';
  const mode = tenant?.businessMode || 'PRODUCT';
  const slides = getSlides(plan, mode, language);
  const [currentSlide, setCurrentSlide] = useState(0);
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    const done = localStorage.getItem(ONBOARDING_KEY);
    if (!done) {
      setIsOpen(true);
    }
  }, []);

  const handleNext = () => {
    if (currentSlide < slides.length - 1) {
      setCurrentSlide(currentSlide + 1);
    } else {
      handleComplete();
    }
  };

  const handlePrev = () => {
    if (currentSlide > 0) {
      setCurrentSlide(currentSlide - 1);
    }
  };

  const handleComplete = () => {
    localStorage.setItem(ONBOARDING_KEY, 'true');
    setIsOpen(false);
  };

  const handleSkip = () => {
    handleComplete();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-4">
      <div className="bg-white dark:bg-gray-800 rounded-3xl w-full max-w-md overflow-hidden shadow-2xl">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b dark:border-gray-700">
          <div className="flex items-center gap-2">
            <span className="text-xl">≡ƒÅ¬</span>
            <span className="font-bold text-gray-900 dark:text-white">KABRAK Store</span>
          </div>
          <button
            onClick={handleSkip}
            className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Content */}
        <div className="p-8 text-center">
          <div className="text-6xl mb-6">{slides[currentSlide].icon}</div>
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white mb-3">
            {slides[currentSlide].title}
          </h2>
          <p className="text-gray-600 dark:text-gray-400 text-sm leading-relaxed">
            {slides[currentSlide].description}
          </p>
        </div>

        {/* Dots */}
        <div className="flex justify-center gap-2 pb-4">
          {slides.map((_, i) => (
            <div
              key={i}
              className={`w-2 h-2 rounded-full transition-all ${
                i === currentSlide ? 'bg-violet-600 w-6' : 'bg-gray-300 dark:bg-gray-600'
              }`}
            />
          ))}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between p-4 border-t dark:border-gray-700">
          <button
            onClick={handlePrev}
            disabled={currentSlide === 0}
            className="flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-medium text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
          >
            <ChevronLeft className="w-4 h-4" />
            {fr ? 'Pr├⌐c├⌐dent' : 'Previous'}
          </button>
          <button
            onClick={handleNext}
            className="flex items-center gap-2 px-6 py-2 rounded-xl bg-violet-600 text-white text-sm font-bold hover:bg-violet-700 transition-colors"
          >
            {currentSlide === slides.length - 1 ? (
              <>
                <CheckCircle className="w-4 h-4" />
                {fr ? 'Commencer' : 'Get Started'}
              </>
            ) : (
              <>
                {fr ? 'Suivant' : 'Next'}
                <ChevronRight className="w-4 h-4" />
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

import * as React from 'react';
import { cva, type VariantProps } from 'class-variance-authority';
import { cn } from '@/lib/utils';

const badgeVariants = cva(
  'inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2',
  {
    variants: {
      variant: {
        default: 'border-transparent bg-primary text-primary-foreground shadow',
        secondary: 'border-transparent bg-secondary text-secondary-foreground',
        destructive: 'border-transparent bg-destructive text-destructive-foreground shadow',
        outline: 'text-foreground',
        success: 'border-transparent bg-emerald-500 text-white shadow',
        warning: 'border-transparent bg-amber-500 text-white shadow',
        gold: 'border-transparent bg-gold-500 text-white shadow',
      },
    },
    defaultVariants: {
      variant: 'default',
    },
  }
);

export interface BadgeProps extends React.HTMLAttributes<HTMLDivElement>, VariantProps<typeof badgeVariants> {}

function Badge({ className, variant, ...props }: BadgeProps) {
  return <div className={cn(badgeVariants({ variant }), className)} {...props} />;
}

export { Badge, badgeVariants };

import * as React from 'react';
import { Slot } from '@radix-ui/react-slot';
import { cva, type VariantProps } from 'class-variance-authority';
import { cn } from '@/lib/utils';

const buttonVariants = cva(
  'inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-lg text-sm font-medium transition-all duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 cursor-pointer',
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground shadow-sm hover:bg-primary/90',
        destructive: 'bg-destructive text-destructive-foreground shadow-sm hover:bg-destructive/90',
        outline: 'border border-input bg-background shadow-sm hover:bg-accent hover:text-accent-foreground',
        secondary: 'bg-secondary text-secondary-foreground shadow-sm hover:bg-secondary/80',
        ghost: 'hover:bg-accent hover:text-accent-foreground',
        link: 'text-primary underline-offset-4 hover:underline',
        gold: 'bg-gold-500 text-white shadow-sm hover:bg-gold-600',
      },
      size: {
        default: 'h-10 px-4 py-2',
        sm: 'h-8 rounded-md px-3 text-xs',
        lg: 'h-12 rounded-lg px-8 text-base',
        icon: 'h-10 w-10',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  }
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : 'button';
    return (
      <Comp className={cn(buttonVariants({ variant, size, className }))} ref={ref} {...props} />
    );
  }
);
Button.displayName = 'Button';

export { Button, buttonVariants };

import { useState } from 'react';
import { Sparkles, TrendingUp, TrendingDown, AlertTriangle, CheckCircle, RefreshCw, DollarSign, BarChart3, Lightbulb, Target, Calendar } from 'lucide-react';
import { useTranslation } from '@/i18n/useTranslation';
import { formatCurrency } from '@/lib/utils';
import api from '@/lib/api';
import { useAuthStore } from '@/stores/authStore';

interface ReportData {
  report: string;
  period: string;
  metrics: {
    totalRevenue: number;
    totalExpenses: number;
    profit: number;
    margin: number;
  };
}

const SECTION_ICONS: Record<number, { icon: typeof Sparkles; color: string; bg: string }> = {
  1: { icon: BarChart3, color: 'text-blue-600', bg: 'bg-blue-50 dark:bg-blue-900/20' },
  2: { icon: CheckCircle, color: 'text-green-600', bg: 'bg-green-50 dark:bg-green-900/20' },
  3: { icon: AlertTriangle, color: 'text-amber-600', bg: 'bg-amber-50 dark:bg-amber-900/20' },
  4: { icon: Lightbulb, color: 'text-purple-600', bg: 'bg-purple-50 dark:bg-purple-900/20' },
  5: { icon: Target, color: 'text-rose-600', bg: 'bg-rose-50 dark:bg-rose-900/20' },
};

function ParsedReport({ text }: { text: string }) {
  const lines = text.split('\n');
  const sections: { title: string; num: number; items: string[] }[] = [];
  let current: { title: string; num: number; items: string[] } | null = null;

  for (const line of lines) {
    const sectionMatch = line.match(/^(\d+)\.\s+(.+)/);
    if (sectionMatch) {
      if (current) sections.push(current);
      current = { num: parseInt(sectionMatch[1]), title: sectionMatch[2], items: [] };
    } else if (current && line.trim().startsWith('-')) {
      current.items.push(line.trim().replace(/^-\s*/, ''));
    } else if (current && line.trim() && !line.match(/^\d+\./)) {
      current.items.push(line.trim());
    }
  }
  if (current) sections.push(current);

  if (sections.length === 0) {
    return (
      <div className="space-y-2">
        {lines.filter(l => l.trim()).map((line, i) => (
          <p key={i} className="text-sm text-gray-700 dark:text-gray-300 leading-relaxed">{line}</p>
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {sections.map((sec) => {
        const cfg = SECTION_ICONS[sec.num] || SECTION_ICONS[1];
        const Icon = cfg.icon;
        return (
          <div key={sec.num} className={`rounded-xl p-4 ${cfg.bg} border border-transparent`}>
            <div className="flex items-center gap-2 mb-3">
              <Icon className={`w-4 h-4 ${cfg.color} flex-shrink-0`} />
              <h3 className={`font-bold text-sm ${cfg.color}`}>{sec.title}</h3>
            </div>
            <ul className="space-y-1.5">
              {sec.items.map((item, i) => (
                <li key={i} className="flex items-start gap-2 text-sm text-gray-700 dark:text-gray-300">
                  <span className="mt-1.5 w-1.5 h-1.5 rounded-full bg-gray-400 flex-shrink-0" />
                  {item}
                </li>
              ))}
            </ul>
          </div>
        );
      })}
    </div>
  );
}

export function AIReportsPage() {
  const { language } = useTranslation();
  const fr = language === 'fr';
  const plan = useAuthStore((s) => s.tenant?.plan || 'STORE');
  const isShop = plan === 'SHOP';
  const [period, setPeriod] = useState<'week' | 'month'>('month');
  const [loading, setLoading] = useState(false);
  const [report, setReport] = useState<ReportData | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [generatedAt, setGeneratedAt] = useState<Date | null>(null);

  const generateReport = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await api.post('/ai/report', { period });
      if (res.data.success) {
        setReport(res.data.data);
        setGeneratedAt(new Date());
      } else {
        setError(res.data.message || 'Erreur inconnue');
      }
    } catch (err: any) {
      const data = err?.response?.data;
      const msg = data?.details
        ? `${data.message} ΓÇö ${data.details}`
        : data?.message || err?.message || 'Erreur de connexion';
      setError(msg);
    } finally {
      setLoading(false);
    }
  };

  const profitPositive = (report?.metrics.profit ?? 0) >= 0;

  return (
    <div className="space-y-5 max-w-4xl mx-auto">

      {/* Header */}
      <div className="bg-gradient-to-r from-purple-600 to-violet-700 rounded-2xl p-5 text-white shadow-lg shadow-purple-200/50">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h1 className="text-xl font-bold flex items-center gap-2">
              <Sparkles className="w-5 h-5" />
              {fr ? 'Rapport IA' : 'AI Report'}
              {isShop && (
                <span className="ml-1 px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-400/30 text-amber-100 border border-amber-300/30">
                  {fr ? '3/mois ┬╖ SHOP' : '3/mo ┬╖ SHOP'}
                </span>
              )}
            </h1>
            <p className="text-purple-200 text-xs mt-1">
              {fr ? 'Analyse intelligente de votre business avec recommandations actionnables' : 'Intelligent business analysis with actionable recommendations'}
            </p>
          </div>
          <div className="flex items-center gap-2 flex-shrink-0">
            <div className="flex rounded-xl overflow-hidden border border-white/30">
              {(['week', 'month'] as const).map((p) => (
                <button
                  key={p}
                  onClick={() => setPeriod(p)}
                  className={`px-3 py-2 text-xs font-bold transition-colors ${period === p ? 'bg-white text-purple-700' : 'text-white/80 hover:text-white hover:bg-white/10'}`}
                >
                  {p === 'week' ? (fr ? '7 jours' : '7 days') : (fr ? 'Ce mois' : 'This month')}
                </button>
              ))}
            </div>
            <button
              onClick={generateReport}
              disabled={loading}
              className="flex items-center gap-2 px-4 py-2 rounded-xl bg-white text-purple-700 font-bold hover:bg-purple-50 disabled:opacity-60 transition-colors text-sm shadow"
            >
              {loading ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
              {fr ? 'G├⌐n├⌐rer' : 'Generate'}
            </button>
          </div>
        </div>
      </div>

      {/* Error */}
      {error && (
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-xl p-4 flex items-start gap-3">
          <AlertTriangle className="w-5 h-5 text-red-500 flex-shrink-0 mt-0.5" />
          <div>
            <p className="font-semibold text-red-700 dark:text-red-400 text-sm">{fr ? 'Erreur' : 'Error'}</p>
            <p className="text-red-600 dark:text-red-300 text-sm mt-0.5">{error}</p>
          </div>
        </div>
      )}

      {/* Loading skeleton */}
      {loading && (
        <div className="space-y-3 animate-pulse">
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
            {[...Array(4)].map((_, i) => <div key={i} className="h-20 bg-gray-100 dark:bg-gray-800 rounded-xl" />)}
          </div>
          <div className="h-96 bg-gray-100 dark:bg-gray-800 rounded-xl" />
        </div>
      )}

      {/* Results */}
      {!loading && report && (
        <>
          {/* Metric cards */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
            <div className="bg-white dark:bg-gray-800 border border-gray-100 dark:border-gray-700 rounded-xl p-4 shadow-sm">
              <div className="flex items-center gap-1.5 mb-2">
                <TrendingUp className="w-4 h-4 text-green-500" />
                <span className="text-xs text-gray-500 font-medium">{fr ? 'Revenus' : 'Revenue'}</span>
              </div>
              <p className="font-black text-lg text-green-600">{formatCurrency(report.metrics.totalRevenue)}</p>
            </div>
            <div className="bg-white dark:bg-gray-800 border border-gray-100 dark:border-gray-700 rounded-xl p-4 shadow-sm">
              <div className="flex items-center gap-1.5 mb-2">
                <TrendingDown className="w-4 h-4 text-red-400" />
                <span className="text-xs text-gray-500 font-medium">{fr ? 'D├⌐penses' : 'Expenses'}</span>
              </div>
              <p className="font-black text-lg text-red-500">{formatCurrency(report.metrics.totalExpenses)}</p>
            </div>
            <div className="bg-white dark:bg-gray-800 border border-gray-100 dark:border-gray-700 rounded-xl p-4 shadow-sm">
              <div className="flex items-center gap-1.5 mb-2">
                <DollarSign className={`w-4 h-4 ${profitPositive ? 'text-blue-500' : 'text-red-400'}`} />
                <span className="text-xs text-gray-500 font-medium">{fr ? 'B├⌐n├⌐fice' : 'Profit'}</span>
              </div>
              <p className={`font-black text-lg ${profitPositive ? 'text-blue-600' : 'text-red-500'}`}>
                {formatCurrency(report.metrics.profit)}
              </p>
            </div>
            <div className="bg-white dark:bg-gray-800 border border-gray-100 dark:border-gray-700 rounded-xl p-4 shadow-sm">
              <div className="flex items-center gap-1.5 mb-2">
                <BarChart3 className={`w-4 h-4 ${profitPositive ? 'text-purple-500' : 'text-red-400'}`} />
                <span className="text-xs text-gray-500 font-medium">{fr ? 'Marge nette' : 'Net margin'}</span>
              </div>
              <p className={`font-black text-lg ${profitPositive ? 'text-purple-600' : 'text-red-500'}`}>
                {report.metrics.margin}%
              </p>
            </div>
          </div>

          {/* Profit bar */}
          {report.metrics.totalRevenue > 0 && (
            <div className="bg-white dark:bg-gray-800 border border-gray-100 dark:border-gray-700 rounded-xl p-4 shadow-sm">
              <div className="flex justify-between text-xs text-gray-500 mb-2">
                <span>{fr ? 'R├⌐partition revenus' : 'Revenue breakdown'}</span>
                <span>{report.metrics.margin}% {fr ? 'de marge' : 'margin'}</span>
              </div>
              <div className="w-full h-3 bg-red-100 rounded-full overflow-hidden">
                <div
                  className="h-full bg-gradient-to-r from-blue-500 to-green-500 rounded-full transition-all duration-700"
                  style={{ width: `${Math.max(0, Math.min(100, report.metrics.margin))}%` }}
                />
              </div>
              <div className="flex justify-between text-[10px] text-gray-400 mt-1">
                <span>{fr ? 'D├⌐penses' : 'Expenses'}: {formatCurrency(report.metrics.totalExpenses)}</span>
                <span>{fr ? 'B├⌐n├⌐fice' : 'Profit'}: {formatCurrency(Math.max(0, report.metrics.profit))}</span>
              </div>
            </div>
          )}

          {/* Report body */}
          <div className="bg-white dark:bg-gray-800 border border-gray-100 dark:border-gray-700 rounded-xl p-5 shadow-sm">
            <div className="flex items-center justify-between mb-4">
              <h2 className="font-bold text-gray-900 dark:text-white flex items-center gap-2">
                <Sparkles className="w-4 h-4 text-purple-500" />
                {fr ? 'Analyse compl├¿te' : 'Full analysis'}
              </h2>
              {generatedAt && (
                <span className="flex items-center gap-1 text-[10px] text-gray-400">
                  <Calendar className="w-3 h-3" />
                  {generatedAt.toLocaleTimeString(fr ? 'fr-FR' : 'en-US', { hour: '2-digit', minute: '2-digit' })}
                </span>
              )}
            </div>
            <ParsedReport text={report.report} />
          </div>

          {/* Regenerate */}
          <div className="text-center">
            <button
              onClick={generateReport}
              className="inline-flex items-center gap-2 px-5 py-2.5 rounded-xl border-2 border-purple-200 text-purple-600 font-semibold text-sm hover:bg-purple-50 transition-colors"
            >
              <RefreshCw className="w-4 h-4" />
              {fr ? 'R├⌐g├⌐n├⌐rer' : 'Regenerate'}
            </button>
          </div>
        </>
      )}

      {/* Empty state */}
      {!loading && !report && !error && (
        <div className="bg-white dark:bg-gray-800 border border-gray-100 dark:border-gray-700 rounded-2xl p-12 text-center shadow-sm">
          <div className="w-16 h-16 rounded-2xl bg-purple-100 dark:bg-purple-900/30 flex items-center justify-center mx-auto mb-4">
            <Sparkles className="w-8 h-8 text-purple-500" />
          </div>
          <h3 className="font-bold text-gray-900 dark:text-white text-lg mb-2">
            {fr ? 'G├⌐n├⌐rez votre rapport IA' : 'Generate your AI report'}
          </h3>
          <p className="text-sm text-gray-400 mb-6 max-w-sm mx-auto">
            {fr
              ? 'GPT-4o analysera vos ventes, d├⌐penses et clients pour vous donner des recommandations concr├¿tes.'
              : 'GPT-4o will analyze your sales, expenses and clients to give you concrete recommendations.'}
          </p>
          <div className="flex flex-wrap justify-center gap-3 mb-8 text-xs text-gray-500">
            {(fr
              ? ['≡ƒôè R├⌐sum├⌐ ex├⌐cutif', 'Γ£à Points forts', 'ΓÜá∩╕Å Axes d\'am├⌐lioration', '≡ƒÆí Recommandations', '≡ƒÄ» Pr├⌐visions']
              : ['≡ƒôè Executive summary', 'Γ£à Strengths', 'ΓÜá∩╕Å Areas to improve', '≡ƒÆí Recommendations', '≡ƒÄ» Forecasts']
            ).map(item => (
              <span key={item} className="px-3 py-1.5 rounded-full bg-purple-50 dark:bg-purple-900/20 text-purple-600 font-medium">{item}</span>
            ))}
          </div>
          <button
            onClick={generateReport}
            className="inline-flex items-center gap-2 px-8 py-3.5 rounded-xl bg-gradient-to-r from-purple-600 to-violet-700 text-white font-bold hover:opacity-90 transition-opacity shadow-lg shadow-purple-200"
          >
            <Sparkles className="w-5 h-5" />
            {fr ? 'Analyser mon business' : 'Analyze my business'}
          </button>
        </div>
      )}
    </div>
  );
}

