import { useEffect, useState, useCallback } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { useTranslation } from '@/i18n/useTranslation';
import { formatCurrency } from '@/lib/utils';
import { Plus, Search, Users, Pencil, Trash2, X, Download, ShoppingCart } from 'lucide-react';
import api from '@/lib/api';

interface Client {
  id: string; name: string; phone?: string; email?: string;
  address?: string; loyaltyPoints: number; totalSpent: number; totalOrders: number;
}

interface Order {
  id: string; reference: string; finalAmount: number;
  paymentStatus: string; status: string; createdAt: string;
}

export function ClientsPage() {
  const { t } = useTranslation();
  const [clients, setClients] = useState<Client[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState({ name: '', phone: '', email: '', address: '' });
  const [historyClient, setHistoryClient] = useState<Client | null>(null);
  const [clientOrders, setClientOrders] = useState<Order[]>([]);
  const [historyLoading, setHistoryLoading] = useState(false);

  const openHistory = async (client: Client) => {
    setHistoryClient(client);
    setHistoryLoading(true);
    try {
      const { data } = await api.get('/orders', { params: { clientId: client.id, limit: 50 } });
      setClientOrders(data.data || []);
    } catch { setClientOrders([]); }
    finally { setHistoryLoading(false); }
  };

  const fetchClients = useCallback(async () => {
    try {
      const { data } = await api.get('/clients', { params: { search, limit: 100 } });
      setClients(data.data);
    } catch (err) { console.error(err); }
    finally { setLoading(false); }
  }, [search]);

  useEffect(() => { fetchClients(); }, [fetchClients]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (editingId) await api.put(`/clients/${editingId}`, form);
      else await api.post('/clients', form);
      setShowForm(false); setEditingId(null); setForm({ name: '', phone: '', email: '', address: '' });
      fetchClients();
    } catch (err) { console.error(err); }
  };

  const handleEdit = (client: Client) => {
    setForm({ name: client.name, phone: client.phone || '', email: client.email || '', address: client.address || '' });
    setEditingId(client.id); setShowForm(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm(t('common.confirm') + '?')) return;
    try {
      await api.delete(`/clients/${id}`);
      fetchClients();
    } catch (err: any) {
      console.error(err);
      const msg = err?.response?.data?.message || t('common.error');
      alert(msg);
    }
  };

  return (
    <div className="space-y-4 sm:space-y-6">
      <div className="flex items-center justify-between gap-2">
        <h1 className="text-xl sm:text-2xl font-bold">{t('clients.title')}</h1>
        <div className="flex gap-2">
          <Button variant="outline" size="sm" onClick={async () => {
            try {
              const res = await api.get('/exports/clients', { responseType: 'blob' });
              const url = URL.createObjectURL(res.data);
              const a = document.createElement('a');
              a.href = url;
              a.download = `clients-${Date.now()}.csv`;
              a.click();
              URL.revokeObjectURL(url);
            } catch (err) { console.error(err); }
          }}>
            <Download className="w-4 h-4 mr-1" /> CSV
          </Button>
          <Button size="sm" onClick={() => { setForm({ name: '', phone: '', email: '', address: '' }); setEditingId(null); setShowForm(true); }}>
            <Plus className="w-4 h-4 mr-1" /> <span className="hidden sm:inline">{t('clients.addClient')}</span><span className="sm:hidden">+</span>
          </Button>
        </div>
      </div>

      <div className="relative max-w-full sm:max-w-md">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
        <Input className="pl-9" placeholder={t('common.search')} value={search} onChange={(e) => setSearch(e.target.value)} />
      </div>

      {showForm && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4">
          <Card className="w-full max-w-md">
            <CardHeader className="flex flex-row items-center justify-between">
              <CardTitle>{editingId ? t('common.edit') : t('clients.addClient')}</CardTitle>
              <Button variant="ghost" size="icon" onClick={() => setShowForm(false)}><X className="w-4 h-4" /></Button>
            </CardHeader>
            <CardContent>
              <form onSubmit={handleSubmit} className="space-y-4">
                <div><label className="text-sm font-medium mb-1 block">{t('clients.name')}</label>
                  <Input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} required /></div>
                <div><label className="text-sm font-medium mb-1 block">{t('clients.phone')}</label>
                  <Input type="tel" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} /></div>
                <div><label className="text-sm font-medium mb-1 block">{t('clients.email')}</label>
                  <Input type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} /></div>
                <div><label className="text-sm font-medium mb-1 block">{t('clients.address')}</label>
                  <Input value={form.address} onChange={(e) => setForm({ ...form, address: e.target.value })} /></div>
                <div className="flex gap-3">
                  <Button type="button" variant="outline" onClick={() => setShowForm(false)} className="flex-1">{t('common.cancel')}</Button>
                  <Button type="submit" className="flex-1">{t('common.save')}</Button>
                </div>
              </form>
            </CardContent>
          </Card>
        </div>
      )}

      {loading ? (
        <div className="flex justify-center py-12"><div className="animate-spin rounded-full h-12 w-12 border-b-2 border-kabrak-500" /></div>
      ) : clients.length === 0 ? (
        <div className="text-center py-12"><Users className="w-16 h-16 mx-auto text-muted-foreground/50 mb-4" /><p className="text-muted-foreground">{t('common.noResults')}</p></div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3 sm:gap-4">
          {clients.map((client) => (
            <Card key={client.id} className="hover:shadow-md transition-shadow">
              <CardContent className="p-3 sm:p-4">
                <div className="flex items-start justify-between mb-3">
                  <div>
                    <h3 className="font-semibold">{client.name}</h3>
                    {client.phone && <p className="text-xs text-muted-foreground">{client.phone}</p>}
                    {client.email && <p className="text-xs text-muted-foreground">{client.email}</p>}
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-2 mb-3 text-center">
                  <div className="bg-muted/50 rounded-lg p-2">
                    <p className="text-xs text-muted-foreground">{t('clients.totalSpent')}</p>
                    <p className="font-semibold text-sm">{formatCurrency(client.totalSpent)}</p>
                  </div>
                  <div className="bg-muted/50 rounded-lg p-2">
                    <p className="text-xs text-muted-foreground">{t('clients.totalOrders')}</p>
                    <p className="font-semibold text-sm">{client.totalOrders}</p>
                  </div>
                </div>
                <div className="flex gap-2">
                  <Button variant="outline" size="sm" onClick={() => openHistory(client)} title="Historique">
                    <ShoppingCart className="w-3 h-3" />
                  </Button>
                  <Button variant="outline" size="sm" className="flex-1" onClick={() => handleEdit(client)}>
                    <Pencil className="w-3 h-3 mr-1" /> {t('common.edit')}
                  </Button>
                  <Button variant="outline" size="sm" onClick={() => handleDelete(client.id)} className="text-destructive hover:text-destructive">
                    <Trash2 className="w-3 h-3" />
                  </Button>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
      {/* Client order history modal */}
      {historyClient && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4">
          <Card className="w-full max-w-lg max-h-[80vh] flex flex-col">
            <CardHeader className="flex flex-row items-center justify-between shrink-0">
              <CardTitle className="text-base">
                <ShoppingCart className="w-4 h-4 inline mr-2" />{historyClient.name}
              </CardTitle>
              <Button variant="ghost" size="icon" onClick={() => setHistoryClient(null)}><X className="w-4 h-4" /></Button>
            </CardHeader>
            <CardContent className="overflow-y-auto">
              {historyLoading ? (
                <div className="flex justify-center py-8"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600" /></div>
              ) : clientOrders.length === 0 ? (
                <p className="text-center text-muted-foreground py-8">Aucune commande</p>
              ) : (
                <div className="space-y-2">
                  {clientOrders.map(order => (
                    <div key={order.id} className="flex items-center justify-between p-3 rounded-lg border border-border hover:bg-muted/50">
                      <div>
                        <p className="font-medium text-sm">{order.reference}</p>
                        <p className="text-xs text-muted-foreground">{new Date(order.createdAt).toLocaleDateString()}</p>
                      </div>
                      <div className="text-right">
                        <p className="font-bold text-sm">{order.finalAmount?.toLocaleString()} XAF</p>
                        <span className={`text-xs px-2 py-0.5 rounded-full ${
                          order.paymentStatus === 'PAID' ? 'bg-green-100 text-green-700' :
                          order.paymentStatus === 'PARTIAL' ? 'bg-amber-100 text-amber-700' :
                          'bg-red-100 text-red-700'
                        }`}>{order.paymentStatus}</span>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </div>
      )}
    </div>
  );
}

