import { useEffect, useState, useRef } from 'react';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { useTranslation } from '@/i18n/useTranslation';
import { useAuthStore } from '@/stores/authStore';
import { formatCurrency, formatDate } from '@/lib/utils';
import { FileText, MessageCircle, Eye, Download, Plus, Trash2, X, DollarSign } from 'lucide-react';
import { InvoiceModal } from '@/components/InvoiceModal';
import api from '@/lib/api';

interface InvoiceItem {
  product: { name: string };
  quantity: number;
  unitPrice: number;
  totalPrice: number;
}

interface LineItem {
  description: string;
  quantity: number;
  unitPrice: number;
}

interface Invoice {
  id: string;
  invoiceNumber: string;
  totalAmount: number;
  amountPaid: number;
  amountDue: number;
  paymentStatus: string;
  createdAt: string;
  client?: { name: string; phone?: string } | null;
  order?: {
    reference: string;
    paymentMethod: string;
    items: InvoiceItem[];
  };
  lineItems?: { description: string; quantity: number; unitPrice: number; totalPrice: number }[];
}

interface Client {
  id: string;
  name: string;
  phone?: string;
}

const statusColors: Record<string, 'success' | 'warning' | 'default'> = {
  PAID: 'success',
  PARTIAL: 'warning',
  PENDING: 'default',
};

export function InvoicesPage() {
  const { t, language } = useTranslation();
  const tenant = useAuthStore((s) => s.tenant);
  const isService = tenant?.businessMode === 'SERVICE';

  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);
  const [selectedInvoice, setSelectedInvoice] = useState<Invoice | null>(null);
  const [showForm, setShowForm] = useState(false);
  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [paymentInvoice, setPaymentInvoice] = useState<Invoice | null>(null);
  const [paymentAmount, setPaymentAmount] = useState('');
  const [paymentMethod, setPaymentMethod] = useState('CASH');
  const [paymentReference, setPaymentReference] = useState('');
  const [paymentNotes, setPaymentNotes] = useState('');
  const [addingPayment, setAddingPayment] = useState(false);
  const mountedRef = useRef(true);

  // Search and filter state
  const [searchQuery, setSearchQuery] = useState('');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [filterPayment, setFilterPayment] = useState('');

  // Standalone invoice form state
  const [clients, setClients] = useState<Client[]>([]);
  const [formClientId, setFormClientId] = useState('');
  const [formNotes, setFormNotes] = useState('');
  const [formDueDate, setFormDueDate] = useState('');
  const [lineItems, setLineItems] = useState<LineItem[]>([{ description: '', quantity: 1, unitPrice: 0 }]);
  const [submitting, setSubmitting] = useState(false);

  const loadInvoices = async () => {
    try {
      const params: Record<string, string | number> = { limit: 50 };
      if (searchQuery) params.search = searchQuery;
      if (dateFrom) params.from = dateFrom;
      if (dateTo) params.to = dateTo;
      if (filterPayment) params.status = filterPayment;
      const { data } = await api.get('/invoices', { params });
      if (mountedRef.current) setInvoices(data.data);
    } catch (err) {
      console.error(err);
      if (mountedRef.current) setError(true);
    } finally {
      if (mountedRef.current) setLoading(false);
    }
  };

  useEffect(() => {
    mountedRef.current = true;
    loadInvoices();
    if (isService) {
      api.get('/clients?limit=200').then(({ data }) => {
        if (mountedRef.current) setClients(data.data || []);
      }).catch(() => {});
    }
    return () => { mountedRef.current = false; };
  }, [isService, searchQuery, dateFrom, dateTo, filterPayment]);

  const handleExport = async () => {
    try {
      const res = await api.get('/exports/invoices', { responseType: 'blob' });
      const url = URL.createObjectURL(res.data);
      const a = document.createElement('a');
      a.href = url;
      a.download = `factures-${Date.now()}.csv`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error(err);
    }
  };

  const addLineItem = () => {
    setLineItems([...lineItems, { description: '', quantity: 1, unitPrice: 0 }]);
  };

  const removeLineItem = (index: number) => {
    if (lineItems.length <= 1) return;
    setLineItems(lineItems.filter((_, i) => i !== index));
  };

  const updateLineItem = (index: number, field: keyof LineItem, value: string | number) => {
    const updated = [...lineItems];
    updated[index] = { ...updated[index], [field]: value };
    setLineItems(updated);
  };

  const formTotal = lineItems.reduce((sum, item) => sum + item.quantity * item.unitPrice, 0);

  const handleCreateStandalone = async () => {
    const validItems = lineItems.filter((li) => li.description.trim() && li.unitPrice > 0);
    if (validItems.length === 0) return;

    setSubmitting(true);
    try {
      await api.post('/invoices/standalone', {
        clientId: formClientId || undefined,
        notes: formNotes || undefined,
        dueDate: formDueDate || undefined,
        items: validItems.map((li) => ({
          description: li.description,
          quantity: li.quantity,
          unitPrice: li.unitPrice,
        })),
      });
      setShowForm(false);
      setFormClientId('');
      setFormNotes('');
      setFormDueDate('');
      setLineItems([{ description: '', quantity: 1, unitPrice: 0 }]);
      setLoading(true);
      loadInvoices();
    } catch (err) {
      console.error(err);
    } finally {
      setSubmitting(false);
    }
  };

  const handleAddPayment = async () => {
    if (!paymentInvoice || !paymentAmount || parseFloat(paymentAmount) <= 0) return;

    setAddingPayment(true);
    try {
      await api.post(`/invoices/${paymentInvoice.id}/payments`, {
        amount: parseFloat(paymentAmount),
        method: paymentMethod,
        reference: paymentReference || undefined,
        notes: paymentNotes || undefined,
      });
      setShowPaymentModal(false);
      setPaymentInvoice(null);
      setPaymentAmount('');
      setPaymentMethod('CASH');
      setPaymentReference('');
      setPaymentNotes('');
      setLoading(true);
      loadInvoices();
    } catch (err) {
      console.error(err);
    } finally {
      setAddingPayment(false);
    }
  };

  const openPaymentModal = (invoice: Invoice) => {
    if (invoice.paymentStatus === 'PAID') return;
    setPaymentInvoice(invoice);
    setPaymentAmount(invoice.amountDue > 0 ? invoice.amountDue.toString() : '');
    setShowPaymentModal(true);
  };

  return (
    <div className="space-y-4 sm:space-y-6">
      <div className="flex items-center justify-between gap-2">
        <h1 className="text-xl sm:text-2xl font-bold dark:text-white">{t('invoices.title')}</h1>
        <div className="flex gap-2">
          {isService && (
            <Button size="sm" onClick={() => setShowForm(!showForm)}>
              <Plus className="w-4 h-4 mr-1" />
              {language === 'fr' ? 'Nouvelle Facture' : 'New Invoice'}
            </Button>
          )}
          <Button variant="outline" size="sm" onClick={handleExport}>
            <Download className="w-4 h-4 mr-2" /> {t('common.export')} CSV
          </Button>
        </div>
      </div>

      {/* Payment status quick filters */}
      <div className="flex gap-2 flex-wrap">
        {[
          { v: '', l: language === 'fr' ? 'Toutes' : 'All' },
          { v: 'PAID', l: language === 'fr' ? 'Pay├⌐es' : 'Paid' },
          { v: 'PARTIAL', l: language === 'fr' ? 'Partielles' : 'Partial' },
          { v: 'PENDING', l: language === 'fr' ? 'Impay├⌐es' : 'Unpaid' },
        ].map(({ v, l }) => (
          <button key={v} onClick={() => setFilterPayment(v)}
            className={`px-3 py-1.5 rounded-full text-xs font-medium border transition-colors ${
              filterPayment === v ? 'bg-blue-600 text-white border-blue-600' : 'border-gray-200 text-gray-600 dark:border-gray-600 dark:text-gray-400 hover:border-blue-300'
            }`}>{l}</button>
        ))}
      </div>

      {/* Search and Filter Bar */}
      <div className="flex flex-wrap gap-3 items-center bg-gray-50 dark:bg-gray-800 p-3 rounded-lg">
        <div className="flex-1 min-w-[200px]">
          <input
            type="text"
            placeholder={language === 'fr' ? 'Rechercher par nom client, num├⌐ro facture...' : 'Search by client name, invoice number...'}
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full rounded-lg border px-3 py-2 text-sm dark:bg-gray-700 dark:border-gray-600 dark:text-white"
          />
        </div>
        <div>
          <input
            type="date"
            value={dateFrom}
            onChange={(e) => setDateFrom(e.target.value)}
            className="rounded-lg border px-3 py-2 text-sm dark:bg-gray-700 dark:border-gray-600 dark:text-white"
          />
        </div>
        <div>
          <input
            type="date"
            value={dateTo}
            onChange={(e) => setDateTo(e.target.value)}
            className="rounded-lg border px-3 py-2 text-sm dark:bg-gray-700 dark:border-gray-600 dark:text-white"
          />
        </div>
        {(searchQuery || dateFrom || dateTo) && (
          <Button
            variant="ghost"
            size="sm"
            onClick={() => {
              setSearchQuery('');
              setDateFrom('');
              setDateTo('');
            }}
            className="text-red-500"
          >
            <X className="w-4 h-4 mr-1" />
            {language === 'fr' ? 'Effacer' : 'Clear'}
          </Button>
        )}
      </div>

      {/* Standalone Invoice Creation Form (SERVICE mode only) */}
      {showForm && isService && (
        <Card className="border-2 border-violet-200 dark:border-violet-800">
          <CardContent className="p-6 space-y-4">
            <div className="flex items-center justify-between">
              <h2 className="text-lg font-semibold dark:text-white">
                {language === 'fr' ? 'Cr├⌐er une facture' : 'Create Invoice'}
              </h2>
              <Button variant="ghost" size="sm" onClick={() => setShowForm(false)}>
                <X className="w-4 h-4" />
              </Button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div>
                <label className="block text-sm font-medium mb-1 dark:text-gray-300">
                  {language === 'fr' ? 'Client' : 'Client'}
                </label>
                <select
                  value={formClientId}
                  onChange={(e) => setFormClientId(e.target.value)}
                  className="w-full rounded-lg border px-3 py-2 text-sm dark:bg-gray-800 dark:border-gray-600 dark:text-white"
                >
                  <option value="">{language === 'fr' ? '-- S├⌐lectionner --' : '-- Select --'}</option>
                  {clients.map((c) => (
                    <option key={c.id} value={c.id}>{c.name}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium mb-1 dark:text-gray-300">
                  {language === 'fr' ? 'Date limite' : 'Due Date'}
                </label>
                <input
                  type="date"
                  value={formDueDate}
                  onChange={(e) => setFormDueDate(e.target.value)}
                  className="w-full rounded-lg border px-3 py-2 text-sm dark:bg-gray-800 dark:border-gray-600 dark:text-white"
                />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1 dark:text-gray-300">
                  {language === 'fr' ? 'Notes' : 'Notes'}
                </label>
                <input
                  type="text"
                  value={formNotes}
                  onChange={(e) => setFormNotes(e.target.value)}
                  placeholder={language === 'fr' ? 'Ex: Gestion r├⌐seaux sociaux mars' : 'E.g. Social media management March'}
                  className="w-full rounded-lg border px-3 py-2 text-sm dark:bg-gray-800 dark:border-gray-600 dark:text-white"
                />
              </div>
            </div>

            {/* Line Items */}
            <div>
              <label className="block text-sm font-medium mb-2 dark:text-gray-300">
                {language === 'fr' ? 'Lignes de facture' : 'Line Items'}
              </label>
              <div className="space-y-2">
                {lineItems.map((item, index) => (
                  <div key={index} className="flex gap-2 items-center">
                    <input
                      type="text"
                      value={item.description}
                      onChange={(e) => updateLineItem(index, 'description', e.target.value)}
                      placeholder={language === 'fr' ? 'Description du service' : 'Service description'}
                      className="flex-1 rounded-lg border px-3 py-2 text-sm dark:bg-gray-800 dark:border-gray-600 dark:text-white"
                    />
                    <input
                      type="number"
                      value={item.quantity}
                      min={1}
                      onChange={(e) => updateLineItem(index, 'quantity', parseInt(e.target.value) || 1)}
                      className="w-20 rounded-lg border px-3 py-2 text-sm text-center dark:bg-gray-800 dark:border-gray-600 dark:text-white"
                      placeholder="Qt├⌐"
                    />
                    <input
                      type="number"
                      value={item.unitPrice === null || item.unitPrice === undefined ? '' : item.unitPrice}
                      min={0}
                      onChange={(e) => updateLineItem(index, 'unitPrice', parseFloat(e.target.value) || 0)}
                      className="w-32 rounded-lg border px-3 py-2 text-sm text-right dark:bg-gray-800 dark:border-gray-600 dark:text-white"
                      placeholder="Prix (FCFA)"
                    />
                    <span className="w-28 text-sm font-medium text-right dark:text-gray-300">
                      {formatCurrency(item.quantity * item.unitPrice)}
                    </span>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => removeLineItem(index)}
                      disabled={lineItems.length <= 1}
                      className="text-red-500 hover:text-red-700"
                    >
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </div>
                ))}
              </div>
              <Button variant="outline" size="sm" onClick={addLineItem} className="mt-2">
                <Plus className="w-4 h-4 mr-1" /> {language === 'fr' ? 'Ajouter ligne' : 'Add line'}
              </Button>
            </div>

            {/* Total + Submit */}
            <div className="flex items-center justify-between pt-4 border-t dark:border-gray-700">
              <div className="text-lg font-bold dark:text-white">
                Total: {formatCurrency(formTotal)}
              </div>
              <Button
                onClick={handleCreateStandalone}
                disabled={submitting || formTotal === 0}
                className="bg-violet-600 hover:bg-violet-700 text-white"
              >
                {submitting
                  ? (language === 'fr' ? 'Cr├⌐ation...' : 'Creating...')
                  : (language === 'fr' ? 'Cr├⌐er la facture' : 'Create Invoice')}
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {loading ? (
        <div className="flex justify-center py-12">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600" />
        </div>
      ) : error ? (
        <div className="text-center py-12">
          <p className="text-red-500 mb-2">{language === 'fr' ? 'Erreur de chargement' : 'Failed to load'}</p>
          <Button variant="outline" onClick={() => { setError(false); loadInvoices(); }}>
            {language === 'fr' ? 'R├⌐essayer' : 'Retry'}
          </Button>
        </div>
      ) : invoices.length === 0 ? (
        <div className="text-center py-12">
          <FileText className="w-16 h-16 mx-auto text-muted-foreground/50 mb-4" />
          <p className="text-muted-foreground dark:text-gray-400">{t('common.noResults')}</p>
          {isService && (
            <Button className="mt-4" onClick={() => setShowForm(true)}>
              <Plus className="w-4 h-4 mr-2" />
              {language === 'fr' ? 'Cr├⌐er votre premi├¿re facture' : 'Create your first invoice'}
            </Button>
          )}
        </div>
      ) : (
        <div className="space-y-3">
          {invoices.map((inv) => (
            <Card key={inv.id} className="hover:shadow-md transition-shadow dark:bg-gray-800">
              <CardContent className="p-4 flex items-center justify-between">
                <div>
                  <p className="font-bold dark:text-white">{inv.invoiceNumber}</p>
                  <p className="text-xs text-muted-foreground dark:text-gray-400">
                    {inv.client?.name || (language === 'fr' ? 'Client anonyme' : 'Anonymous client')} ┬╖ {formatDate(inv.createdAt)}
                  </p>
                  {inv.lineItems && inv.lineItems.length > 0 && !inv.order && (
                    <p className="text-xs text-violet-600 dark:text-violet-400 mt-0.5">
                      {inv.lineItems.map((li) => li.description).join(', ')}
                    </p>
                  )}
                </div>
                <div className="flex items-center gap-2">
                  <div className="text-right mr-2">
                    <p className="font-bold dark:text-white">{formatCurrency(inv.totalAmount)}</p>
                    <Badge variant={statusColors[inv.paymentStatus]}>
                      {t(`status.${inv.paymentStatus.toLowerCase()}`)}
                    </Badge>
                    {inv.paymentStatus === 'PARTIAL' && (
                      <p className="text-xs text-muted-foreground dark:text-gray-400">
                        {formatCurrency(inv.amountPaid)} / {formatCurrency(inv.totalAmount)}
                      </p>
                    )}
                  </div>
                  {inv.paymentStatus !== 'PAID' && (
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => openPaymentModal(inv)}
                      className="text-violet-600 dark:text-violet-400"
                      title="Ajouter paiement"
                    >
                      <DollarSign className="w-4 h-4" />
                    </Button>
                  )}
                  <Button variant="outline" size="sm" onClick={() => setSelectedInvoice(inv)} title="Voir">
                    <Eye className="w-4 h-4" />
                  </Button>
                  {inv.client?.phone && (
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => setSelectedInvoice(inv)}
                      className="text-green-500"
                      title="WhatsApp"
                    >
                      <MessageCircle className="w-4 h-4" />
                    </Button>
                  )}
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {selectedInvoice && (
        <InvoiceModal invoice={selectedInvoice} onClose={() => setSelectedInvoice(null)} />
      )}

      {/* Payment Modal */}
      {showPaymentModal && paymentInvoice && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60">
          <Card className="w-full max-w-md bg-white dark:bg-gray-800">
            <CardContent className="p-6 space-y-4">
              <div className="flex items-center justify-between">
                <h2 className="text-lg font-bold dark:text-white">
                  {language === 'fr' ? 'Ajouter un paiement' : 'Add Payment'}
                </h2>
                <Button variant="ghost" size="sm" onClick={() => setShowPaymentModal(false)}>
                  <X className="w-4 h-4" />
                </Button>
              </div>

              <div className="bg-gray-50 dark:bg-gray-700 rounded-lg p-3 space-y-2">
                <p className="text-sm font-medium dark:text-white">{paymentInvoice.invoiceNumber}</p>
                <div className="flex justify-between text-sm">
                  <span className="text-muted-foreground dark:text-gray-400">
                    {language === 'fr' ? 'Total' : 'Total'}
                  </span>
                  <span className="font-bold dark:text-white">{formatCurrency(paymentInvoice.totalAmount)}</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-muted-foreground dark:text-gray-400">
                    {language === 'fr' ? 'D├⌐j├á pay├⌐' : 'Already paid'}
                  </span>
                  <span className="font-bold dark:text-white">{formatCurrency(paymentInvoice.amountPaid)}</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-muted-foreground dark:text-gray-400">
                    {language === 'fr' ? 'Reste ├á payer' : 'Amount due'}
                  </span>
                  <span className="font-bold text-violet-600 dark:text-violet-400">
                    {formatCurrency(paymentInvoice.amountDue)}
                  </span>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium mb-1 dark:text-gray-300">
                  {language === 'fr' ? 'Montant du paiement' : 'Payment amount'}
                </label>
                <input
                  type="number"
                  value={paymentAmount}
                  onChange={(e) => setPaymentAmount(e.target.value)}
                  className="w-full rounded-lg border px-3 py-2 text-sm dark:bg-gray-800 dark:border-gray-600 dark:text-white"
                  placeholder={language === 'fr' ? 'Montant en FCFA' : 'Amount in FCFA'}
                />
              </div>

              <div>
                <label className="block text-sm font-medium mb-1 dark:text-gray-300">
                  {language === 'fr' ? 'M├⌐thode de paiement' : 'Payment method'}
                </label>
                <select
                  value={paymentMethod}
                  onChange={(e) => setPaymentMethod(e.target.value)}
                  className="w-full rounded-lg border px-3 py-2 text-sm dark:bg-gray-800 dark:border-gray-600 dark:text-white"
                >
                  <option value="CASH">{language === 'fr' ? 'Esp├¿ces' : 'Cash'}</option>
                  <option value="ORANGE_MONEY">Orange Money</option>
                  <option value="MTN_MOMO">MTN Mobile Money</option>
                  <option value="BANK_TRANSFER">{language === 'fr' ? 'Virement bancaire' : 'Bank transfer'}</option>
                  <option value="OTHER">{language === 'fr' ? 'Autre' : 'Other'}</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium mb-1 dark:text-gray-300">
                  {language === 'fr' ? 'R├⌐f├⌐rence (optionnel)' : 'Reference (optional)'}
                </label>
                <input
                  type="text"
                  value={paymentReference}
                  onChange={(e) => setPaymentReference(e.target.value)}
                  className="w-full rounded-lg border px-3 py-2 text-sm dark:bg-gray-800 dark:border-gray-600 dark:text-white"
                  placeholder={language === 'fr' ? 'Num├⌐ro de transaction' : 'Transaction number'}
                />
              </div>

              <div>
                <label className="block text-sm font-medium mb-1 dark:text-gray-300">
                  {language === 'fr' ? 'Notes (optionnel)' : 'Notes (optional)'}
                </label>
                <input
                  type="text"
                  value={paymentNotes}
                  onChange={(e) => setPaymentNotes(e.target.value)}
                  className="w-full rounded-lg border px-3 py-2 text-sm dark:bg-gray-800 dark:border-gray-600 dark:text-white"
                  placeholder={language === 'fr' ? 'D├⌐tails du paiement' : 'Payment details'}
                />
              </div>

              <div className="flex gap-2 pt-2">
                <Button
                  variant="outline"
                  className="flex-1"
                  onClick={() => setShowPaymentModal(false)}
                >
                  {language === 'fr' ? 'Annuler' : 'Cancel'}
                </Button>
                <Button
                  className="flex-1 bg-violet-600 hover:bg-violet-700 text-white"
                  onClick={handleAddPayment}
                  disabled={addingPayment || !paymentAmount || parseFloat(paymentAmount) <= 0}
                >
                  {addingPayment
                    ? (language === 'fr' ? 'Ajout...' : 'Adding...')
                    : (language === 'fr' ? 'Ajouter' : 'Add')}
                </Button>
              </div>
            </CardContent>
          </Card>
        </div>
      )}
    </div>
  );
}

import { useEffect, useState, useCallback } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { useTranslation } from '@/i18n/useTranslation';
import { useAuthStore } from '@/stores/authStore';
import { formatCurrency, formatDateTime } from '@/lib/utils';
import { Plus, ShoppingCart, X, MessageCircle } from 'lucide-react';
import api from '@/lib/api';

interface OrderItem {
  id: string;
  quantity: number;
  unitPrice: number;
  totalPrice: number;
  variant?: string;
  product: { id: string; name: string };
}

interface Order {
  id: string;
  reference: string;
  status: string;
  totalAmount: number;
  finalAmount: number;
  notes?: string;
  createdAt: string;
  client?: { id: string; name: string; phone?: string } | null;
  items: OrderItem[];
  createdBy: { firstName: string; lastName: string };
  invoice?: {
    id: string;
    invoiceNumber: string;
    totalAmount: number;
    amountPaid: number;
    amountDue: number;
    paymentStatus: string;
  };
}

interface Product {
  id: string;
  name: string;
  sellingPrice: number;
  totalStock: number;
  image?: string;
}

interface Client {
  id: string;
  name: string;
  phone?: string;
}

const statusColors: Record<string, 'default' | 'success' | 'warning' | 'destructive'> = {
  PENDING: 'warning', CONFIRMED: 'default', PREPARING: 'default',
  READY: 'success', DELIVERING: 'default', DELIVERED: 'success', CANCELLED: 'destructive',
  PAID: 'success', PARTIAL: 'warning',
};

interface CartItem {
  productId: string;
  name: string;
  quantity: number;
  unitPrice: number;
  variant?: string;
}

const ORDER_BASED_CATS = new Set([
  'CAKES', 'FOOD_BUSINESS', 'FOOD_DELIVERY', 'HOME_COOKING', 'MADE_TO_ORDER', 'WHATSAPP_SELLER',
]);

export function OrdersPage() {
  const { t, language } = useTranslation();
  const tenant = useAuthStore((s) => s.tenant);
  const businessCategories = tenant?.businessCategories || [];
  const isOrderBased = !!(businessCategories.length &&
    businessCategories.every((cat) => ORDER_BASED_CATS.has(cat)));

  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [products, setProducts] = useState<Product[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [selectedClient, setSelectedClient] = useState('');
  const [discount, setDiscount] = useState<number | ''>('');
  const [deliveryDate, setDeliveryDate] = useState('');
  // Initial payment (optional, goes to invoice)
  const [initialPaymentMethod, setInitialPaymentMethod] = useState('CASH');
  const [initialAmountPaid, setInitialAmountPaid] = useState<number | ''>('');

  // Search and filter state
  const [searchQuery, setSearchQuery] = useState('');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [filterPayment, setFilterPayment] = useState('');

  const fetchOrders = useCallback(async () => {
    try {
      const params: any = { limit: 50 };
      if (searchQuery) params.search = searchQuery;
      if (dateFrom) params.from = dateFrom;
      if (dateTo) params.to = dateTo;
      const { data } = await api.get('/orders', { params });
      setOrders(data.data);
    } catch (err) { console.error(err); }
    finally { setLoading(false); }
  }, [searchQuery, dateFrom, dateTo]);

  useEffect(() => { fetchOrders(); }, [fetchOrders]);

  const openNewOrder = async () => {
    const [prodRes, clientRes] = await Promise.all([
      api.get('/products', { params: { limit: 200 } }),
      api.get('/clients', { params: { limit: 200 } }),
    ]);
    setProducts(prodRes.data.data);
    setClients(clientRes.data.data);
    setCart([]);
    setSelectedClient('');
    setInitialAmountPaid('');
    setDiscount('');
    setDeliveryDate('');
    setInitialPaymentMethod('CASH');
    setShowForm(true);
  };

  const addToCart = (product: Product) => {
    setCart((prev) => {
      const existing = prev.find((i) => i.productId === product.id);
      if (existing) {
        return prev.map((i) => i.productId === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { productId: product.id, name: product.name, quantity: 1, unitPrice: product.sellingPrice }];
    });
  };

  const cartTotal = cart.reduce((sum, i) => sum + i.unitPrice * i.quantity, 0);
  const finalTotal = cartTotal - (Number(discount) || 0);

  const handleCreateOrder = async () => {
    try {
      await api.post('/orders', {
        clientId: selectedClient || undefined,
        items: cart.map((i) => ({ productId: i.productId, quantity: i.quantity, unitPrice: i.unitPrice, variant: i.variant })),
        discount: Number(discount) || 0,
        paymentMethod: initialPaymentMethod,
        amountPaid: Number(initialAmountPaid) || 0,
        deliveryDate: isOrderBased ? deliveryDate : undefined,
      });
      setShowForm(false);
      fetchOrders();
    } catch (err: unknown) {
      const axiosErr = err as { response?: { data?: { message?: string } } };
      alert(axiosErr.response?.data?.message || "Erreur lors de la cr├⌐ation de la commande");
      console.error(err);
    }
  };

  const handleWhatsApp = (order: Order) => {
    const phone = order.client?.phone?.replace(/\s+/g, '').replace('+', '');
    if (!phone) return;
    const items = order.items.map((i) => `${i.product.name} x${i.quantity} = ${formatCurrency(i.totalPrice)}`).join('\n');
    const storeName = tenant?.name || 'KABRAK';
    const invoice = order.invoice;
    const message = encodeURIComponent(
      `*${storeName} - ${t('orders.whatsappMessage.invoice')}*\n\n${t('orders.whatsappMessage.ref')}: ${order.reference}\n\n${items}\n\n` +
      `${t('orders.whatsappMessage.total')}: ${formatCurrency(order.finalAmount)}\n` +
      (invoice ? `${t('orders.whatsappMessage.paid')}: ${formatCurrency(invoice.amountPaid)}\n${t('orders.whatsappMessage.remaining')}: ${formatCurrency(invoice.amountDue)}\n` : '') +
      `\n${t('orders.whatsappMessage.thanks')}`
    );
    window.open(`https://wa.me/${phone}?text=${message}`, '_blank');
  };

  const updateOrderStatus = async (orderId: string, newStatus: string) => {
    try {
      await api.patch(`/orders/${orderId}/status`, { status: newStatus });
      fetchOrders();
    } catch (err) {
      console.error(err);
      alert('Erreur lors de la mise ├á jour du statut');
    }
  };

  return (
    <div className="space-y-4 sm:space-y-6">
      <div className="flex items-center justify-between">
        <h1 className="text-xl sm:text-2xl font-bold">{t('orders.title')}</h1>
        <Button size="sm" onClick={openNewOrder}>
          <Plus className="w-4 h-4 mr-1" /> {t('orders.newOrder')}
        </Button>
      </div>

      {/* Payment filter chips */}
      <div className="flex gap-2 flex-wrap">
        {[{ v: '', l: language === 'fr' ? 'Toutes' : 'All' }, { v: 'PAID', l: language === 'fr' ? 'Pay├⌐es' : 'Paid' }, { v: 'PARTIAL', l: language === 'fr' ? 'Partielles' : 'Partial' }, { v: 'PENDING', l: language === 'fr' ? 'Impay├⌐es' : 'Unpaid' }].map(({ v, l }) => (
          <button key={v} onClick={() => setFilterPayment(v)}
            className={`px-3 py-1.5 rounded-full text-xs font-medium border transition-colors ${
              filterPayment === v ? 'bg-blue-600 text-white border-blue-600' : 'border-gray-200 text-gray-600 dark:border-gray-600 dark:text-gray-400 hover:border-blue-300'
            }`}>{l}</button>
        ))}
      </div>

      {/* Search and Filter Bar */}
      <div className="flex flex-wrap gap-3 items-center bg-gray-50 dark:bg-gray-800 p-3 rounded-lg">
        <div className="flex-1 min-w-[200px]">
          <Input
            placeholder={t('common.search')}
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
        <div className="flex-1 min-w-[140px]">
          <Input
            type="date"
            placeholder={t('common.from')}
            value={dateFrom}
            onChange={(e) => setDateFrom(e.target.value)}
          />
        </div>
        <div className="flex-1 min-w-[140px]">
          <Input
            type="date"
            placeholder={t('common.to')}
            value={dateTo}
            onChange={(e) => setDateTo(e.target.value)}
          />
        </div>
        {(searchQuery || dateFrom || dateTo) && (
          <Button
            variant="ghost"
            size="sm"
            onClick={() => {
              setSearchQuery('');
              setDateFrom('');
              setDateTo('');
            }}
            className="text-red-500"
          >
            <X className="w-4 h-4 mr-1" />
            {t('common.clear')}
          </Button>
        )}
      </div>

      {/* New Order Modal */}
      {showForm && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4">
          <Card className="w-full max-w-3xl max-h-[90vh] overflow-y-auto">
            <CardHeader className="flex flex-row items-center justify-between">
              <CardTitle>{t('orders.newOrder')}</CardTitle>
              <Button variant="ghost" size="icon" onClick={() => setShowForm(false)}><X className="w-4 h-4" /></Button>
            </CardHeader>
            <CardContent className="space-y-4">
              {/* Client Selection */}
              <div>
                <label className="text-sm font-medium mb-1 block">{t('clients.title')}</label>
                <select className="w-full rounded-lg border border-input bg-background px-3 py-2 text-sm"
                  value={selectedClient} onChange={(e) => setSelectedClient(e.target.value)}>
                  <option value="">-- Client anonyme --</option>
                  {clients.map((c) => <option key={c.id} value={c.id}>{c.name} {c.phone ? `(${c.phone})` : ''}</option>)}
                </select>
              </div>

              {/* Product selection */}
              <div>
                <label className="text-sm font-medium mb-1 block">{t('products.title')}</label>
                <div className="grid grid-cols-2 sm:grid-cols-3 gap-2 max-h-48 overflow-y-auto">
                  {products.map((p) => (
                    <button key={p.id} onClick={() => addToCart(p)} type="button"
                      className="text-left border rounded-lg hover:border-kabrak-500 transition-colors cursor-pointer text-xs overflow-hidden">
                      {p.image ? (
                        <img src={p.image} alt={p.name} className="w-full h-16 object-cover" />
                      ) : (
                        <div className="w-full h-16 bg-gray-100 dark:bg-gray-800 flex items-center justify-center">
                          <ShoppingCart className="w-5 h-5 text-muted-foreground/30" />
                        </div>
                      )}
                      <div className="p-1.5">
                        <p className="font-medium truncate">{p.name}</p>
                        <p className="text-muted-foreground">{formatCurrency(p.sellingPrice)} ┬╖ {p.totalStock}</p>
                      </div>
                    </button>
                  ))}
                </div>
              </div>

              {/* Cart */}
              {cart.length > 0 && (
                <div className="border rounded-lg p-3 space-y-2">
                  {cart.map((item, i) => (
                    <div key={i} className="flex items-center justify-between text-sm">
                      <span className="font-medium">{item.name}</span>
                      <div className="flex items-center gap-2">
                        <Input type="number" className="w-16 h-8 text-center" min={1} value={item.quantity}
                          onChange={(e) => setCart((prev) => prev.map((ci, ci2) => ci2 === i ? { ...ci, quantity: +e.target.value } : ci))} />
                        <span className="w-24 text-right">{formatCurrency(item.unitPrice * item.quantity)}</span>
                        <Button variant="ghost" size="sm" onClick={() => setCart((prev) => prev.filter((_, ci2) => ci2 !== i))}>
                          <X className="w-3 h-3" />
                        </Button>
                      </div>
                    </div>
                  ))}
                  <div className="border-t pt-2 space-y-1">
                    <div className="flex justify-between text-sm"><span>Sous-total</span><span>{formatCurrency(cartTotal)}</span></div>
                    <div className="flex justify-between items-center text-sm">
                      <span>Remise</span>
                      <Input type="number" className="w-24 h-8 text-right" value={discount} placeholder="0" onChange={(e) => setDiscount(e.target.value === '' ? '' : +e.target.value)} />
                    </div>
                    <div className="flex justify-between font-bold"><span>Total</span><span>{formatCurrency(finalTotal)}</span></div>
                  </div>
                </div>
              )}

              {isOrderBased && (
                <div>
                  <label className="text-sm font-medium mb-1 block">{t('delivery.deliveryDate')}</label>
                  <Input type="date" placeholder="YYYY-MM-DD" value={deliveryDate} onChange={(e) => setDeliveryDate(e.target.value)} />
                </div>
              )}

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-sm font-medium mb-1 block">{t('orders.paymentMethod')}</label>
                  <select className="w-full rounded-lg border border-input bg-background px-3 py-2 text-sm"
                    value={initialPaymentMethod} onChange={(e) => setInitialPaymentMethod(e.target.value)}>
                    <option value="CASH">Cash</option>
                    <option value="MOBILE_MONEY">Mobile Money</option>
                    <option value="BANK_TRANSFER">Virement bancaire</option>
                    <option value="OTHER">Autre</option>
                  </select>
                </div>
                <div>
                  <label className="text-sm font-medium mb-1 block">{t('orders.paid')} (FCFA)</label>
                  <Input type="number" value={initialAmountPaid} placeholder="0" onChange={(e) => setInitialAmountPaid(e.target.value === '' ? '' : +e.target.value)} />
                </div>
              </div>

              <div className="flex gap-3">
                <Button variant="outline" onClick={() => setShowForm(false)} className="flex-1">{t('common.cancel')}</Button>
                <Button onClick={handleCreateOrder} className="flex-1" disabled={cart.length === 0}>{t('common.save')}</Button>
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Orders List */}
      {loading ? (
        <div className="flex justify-center py-12">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-kabrak-500" />
        </div>
      ) : orders.length === 0 ? (
        <div className="text-center py-12">
          <ShoppingCart className="w-16 h-16 mx-auto text-muted-foreground/50 mb-4" />
          <p className="text-muted-foreground">{t('common.noResults')}</p>
        </div>
      ) : (
        <div className="space-y-2 sm:space-y-3">
          {orders.filter(o => !filterPayment || o.invoice?.paymentStatus === filterPayment).map((order) => (
            <Card key={order.id} className="hover:shadow-md transition-shadow">
              <CardContent className="p-3 sm:p-4">
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2">
                  <div className="min-w-0">
                    <p className="font-bold text-sm sm:text-base">{order.reference}</p>
                    <p className="text-xs text-muted-foreground truncate">
                      {order.client?.name || 'Client anonyme'} ┬╖ {formatDateTime(order.createdAt)}
                    </p>
                  </div>
                  <div className="flex items-center justify-between sm:justify-end gap-2 sm:gap-3">
                    <div className="sm:text-right">
                      <p className="font-bold text-sm sm:text-base">{formatCurrency(order.finalAmount)}</p>
                      <div className="flex gap-1">
                        <Badge variant={statusColors[order.status]} className="text-[10px]">{t(`status.${order.status.toLowerCase()}`)}</Badge>
                        {order.invoice && (
                          <Badge variant={statusColors[order.invoice.paymentStatus]} className="text-[10px]">{t(`status.${order.invoice.paymentStatus.toLowerCase()}`)}</Badge>
                        )}
                      </div>
                    </div>
                    <div className="flex gap-1">
                      <select
                        value={order.status}
                        onChange={(e) => updateOrderStatus(order.id, e.target.value)}
                        className="text-xs border rounded px-1 py-1 bg-background"
                      >
                        <option value="PENDING">En attente</option>
                        <option value="CONFIRMED">Confirm├⌐e</option>
                        <option value="PREPARING">En pr├⌐paration</option>
                        <option value="READY">Pr├¬te</option>
                        <option value="DELIVERING">En livraison</option>
                        <option value="DELIVERED">Livr├⌐e</option>
                        <option value="CANCELLED">Annul├⌐e</option>
                      </select>
                      {order.client?.phone && (
                        <Button variant="outline" size="sm" className="h-8 w-8 p-0" onClick={() => handleWhatsApp(order)} title={t('orders.sendWhatsApp')}>
                          <MessageCircle className="w-4 h-4 text-green-500" />
                        </Button>
                      )}
                    </div>
                  </div>
                </div>
                <div className="mt-2 flex flex-wrap gap-1">
                  {order.items.map((item) => (
                    <span key={item.id} className="text-[10px] sm:text-xs bg-muted px-1.5 sm:px-2 py-0.5 sm:py-1 rounded">
                      {item.product.name} x{item.quantity}
                    </span>
                  ))}
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState, useCallback } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent } from '@/components/ui/card';
import { useTranslation } from '@/i18n/useTranslation';
import { useAuthStore } from '@/stores/authStore';
import { formatCurrency } from '@/lib/utils';
import { Search, Plus, Minus, Trash2, ShoppingCart, ScanLine, User, CreditCard, Banknote, Smartphone, X } from 'lucide-react';
import { BarcodeScanner } from '@/components/BarcodeScanner';
import { InvoiceModal } from '@/components/InvoiceModal';
import api from '@/lib/api';

interface Product {
  id: string;
  name: string;
  sellingPrice: number;
  totalStock: number;
  image?: string;
  businessType: string;
  adaptiveFields?: Record<string, unknown>;
}

interface CartItem {
  product: Product;
  quantity: number;
  variant?: string;
}

interface Client {
  id: string;
  name: string;
  phone?: string;
}

export function POSPage() {
  const { t, language } = useTranslation();
  const tenant = useAuthStore((s) => s.tenant);
  const [products, setProducts] = useState<Product[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [search, setSearch] = useState('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [clientSearch, setClientSearch] = useState('');
  const [showClientPicker, setShowClientPicker] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<'CASH' | 'ORANGE_MONEY' | 'MTN_MOMO' | 'BANK_TRANSFER'>('CASH');
  const [amountPaid, setAmountPaid] = useState(0);
  const [processing, setProcessing] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);
  const [discount, setDiscount] = useState(0);
  const [notes, setNotes] = useState('');
  const [showInvoice, setShowInvoice] = useState(false);
  const [completedInvoice, setCompletedInvoice] = useState<unknown>(null);
  const [variantPicker, setVariantPicker] = useState<{ product: Product; sizes: string[] } | null>(null);

  const canScan = tenant?.plan === 'SHOP' || tenant?.plan === 'BUSINESS';

  const fetchProducts = useCallback(async () => {
    try {
      const { data } = await api.get('/products', { params: { search, limit: 50, isService: false } });
      setProducts(data.data || []);
    } catch (err) { console.error(err); }
  }, [search]);

  const fetchClients = useCallback(async () => {
    try {
      const { data } = await api.get('/clients', { params: { search: clientSearch, limit: 20 } });
      setClients(data.data || []);
    } catch (err) { console.error(err); }
  }, [clientSearch]);

  useEffect(() => { fetchProducts(); }, [fetchProducts]);
  useEffect(() => { if (showClientPicker) fetchClients(); }, [showClientPicker, fetchClients]);

  const parseSizes = (sizesStr: string): string[] =>
    sizesStr.split(',').map(s => s.trim()).filter(s => s.includes(':'));

  const addToCart = (product: Product, variant?: string) => {
    // If HIJABS_ABAYAS or product has sizes, show picker first
    const sizesStr = product.adaptiveFields?.sizes as string | undefined;
    if (!variant && sizesStr && sizesStr.includes(':')) {
      setVariantPicker({ product, sizes: parseSizes(sizesStr) });
      return;
    }
    setCart(prev => {
      const existing = prev.find(item => (variant ? item.variant === variant && item.product.id === product.id : item.product.id === product.id && !item.variant));
      if (existing) {
        return prev.map(item =>
          (variant ? item.variant === variant && item.product.id === product.id : item.product.id === product.id && !item.variant)
            ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { product, quantity: 1, variant }];
    });
    setVariantPicker(null);
  };

  const updateQuantity = (productId: string, delta: number, variant?: string) => {
    setCart(prev => prev
      .map(item => {
        if (item.product.id !== productId) return item;
        if (variant !== undefined && item.variant !== variant) return item;
        const newQty = item.quantity + delta;
        if (newQty <= 0) return null;
        return { ...item, quantity: newQty };
      })
      .filter(Boolean) as CartItem[]
    );
  };

  const removeFromCart = (productId: string, variant?: string) => {
    setCart(prev => prev.filter(item => !(item.product.id === productId && item.variant === variant)));
  };

  const subtotal = cart.reduce((sum, item) => sum + (item.product.sellingPrice * item.quantity), 0);
  const total = Math.max(0, subtotal - discount);
  const change = amountPaid > total ? amountPaid - total : 0;
  const paymentStatus = amountPaid >= total ? 'PAID' : amountPaid > 0 ? 'PARTIAL' : 'PENDING';

  const handleBarcodeScan = async (code: string) => {
    try {
      const { data } = await api.get(`/products/barcode/${code}`);
      if (data.data) {
        addToCart(data.data);
        setShowScanner(false);
      }
    } catch {
      alert(language === 'fr' ? 'Produit non trouv├⌐' : 'Product not found');
    }
  };

  const handleCheckout = async () => {
    if (cart.length === 0) return;
    setProcessing(true);
    try {
      const res = await api.post('/orders', {
        clientId: selectedClient?.id || null,
        paymentMethod,
        amountPaid: Math.min(amountPaid, total),
        discount,
        notes: notes || undefined,
        items: cart.map(item => ({
          productId: item.product.id,
          quantity: item.quantity,
          unitPrice: item.product.sellingPrice,
          variant: item.variant || undefined,
        })),
      });
      const orderData = res.data.data;
      // Show invoice immediately if created
      if (orderData?.invoice) {
        setCompletedInvoice({ ...orderData.invoice, client: orderData.client, order: { reference: orderData.reference, paymentMethod, items: orderData.items } });
        setShowInvoice(true);
      } else {
        setShowSuccess(true);
        setTimeout(() => setShowSuccess(false), 3000);
      }
      resetData();
      fetchProducts();
    } catch (err) {
      console.error(err);
      const errorMsg = err instanceof Error && err.message ? err.message : (language === 'fr' ? 'Erreur lors de la vente' : 'Error during sale');
      alert(errorMsg);
    }
    setProcessing(false);
  };

  const resetData = () => {
    setCart([]);
    setSelectedClient(null);
    setAmountPaid(0);
    setDiscount(0);
    setNotes('');
    setPaymentMethod('CASH');
  };

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      const tag = (e.target as HTMLElement).tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
      if (e.key === 'Enter' && cart.length > 0 && !processing) handleCheckout();
      if (e.key === 'Escape' && cart.length > 0) resetData();
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [cart, processing]);

  const renderClientPicker = () => {
    if (!showClientPicker) return null;
    return (
      <div className="fixed inset-0 z-[100] bg-black/60 flex items-center justify-center p-4">
        <Card className="w-full max-w-md shadow-2xl">
          <CardContent className="p-4 space-y-3">
            <div className="flex items-center justify-between">
              <h3 className="font-bold">{language === 'fr' ? 'Choisir un client' : 'Select client'}</h3>
              <button onClick={() => setShowClientPicker(false)} className="p-1 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg"><X className="w-5 h-5" /></button>
            </div>
            <Input
              placeholder={language === 'fr' ? 'Chercher...' : 'Search...'}
              value={clientSearch}
              onChange={(e) => setClientSearch(e.target.value)}
            />
            <div className="max-h-60 overflow-y-auto space-y-1">
              {clients.map(client => (
                <button
                  key={client.id}
                  onClick={() => { setSelectedClient(client); setShowClientPicker(false); }}
                  className="w-full text-left px-3 py-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
                >
                  <p className="text-sm font-medium">{client.name}</p>
                  {client.phone && <p className="text-xs text-gray-400">{client.phone}</p>}
                </button>
              ))}
              {clients.length === 0 ? (
                <p className="text-sm text-gray-400 text-center py-4">{t('common.noResults')}</p>
              ) : null}
            </div>
          </CardContent>
        </Card>
      </div>
    );
  };

  return (
    <div className="h-[calc(100vh-3.5rem)] sm:h-[calc(100vh-4rem)] flex flex-col lg:flex-row gap-3 sm:gap-4 overflow-hidden">
      {/* Left: Products */}
      <div className="flex-1 flex flex-col min-w-0 min-h-0">
        <div className="flex items-center gap-2 mb-3 sm:mb-4">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <Input
              className="pl-9"
              placeholder={language === 'fr' ? 'Chercher un produit...' : 'Search product...'}
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>
          {canScan ? (
            <Button variant="outline" size="default" onClick={() => setShowScanner(true)}>
              <ScanLine className="w-4 h-4" />
            </Button>
          ) : null}
        </div>

        <div className="flex-1 overflow-y-auto">
          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-2">
            {products.map((product) => {
              const inCart = cart.find(item => item.product.id === product.id);
              const isOutOfStock = product.totalStock <= 0;
              return (
                <button
                  key={product.id}
                  onClick={() => !isOutOfStock && addToCart(product)}
                  disabled={isOutOfStock}
                  className={`rounded-xl border text-left transition-all cursor-pointer overflow-hidden ${
                    isOutOfStock
                      ? 'opacity-40 cursor-not-allowed bg-gray-50 dark:bg-gray-800/50'
                      : inCart
                        ? 'border-blue-300 bg-blue-50 dark:bg-blue-900/20 shadow-sm'
                        : 'border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 hover:border-blue-200 hover:shadow-sm'
                  }`}
                >
                  {product.image ? (
                    <img src={product.image} alt={product.name} className="w-full h-20 object-cover" />
                  ) : (
                    <div className="w-full h-20 bg-gray-100 dark:bg-gray-700 flex items-center justify-center">
                      <ShoppingCart className="w-6 h-6 text-gray-300" />
                    </div>
                  )}
                  <div className="p-2">
                    <p className="font-medium text-sm text-gray-900 dark:text-white truncate">{product.name}</p>
                    <p className="text-xs text-gray-400 mt-0.5">{product.totalStock} {language === 'fr' ? 'en stock' : 'in stock'}</p>
                    <div className="flex items-center justify-between mt-1">
                      <p className="font-bold text-sm text-blue-600">{formatCurrency(product.sellingPrice)}</p>
                      {inCart ? (
                        <span className="w-5 h-5 rounded-full bg-blue-600 text-white text-xs flex items-center justify-center font-bold">
                          {inCart.quantity}
                        </span>
                      ) : null}
                    </div>
                  </div>
                </button>
              );
            })}
          </div>
        </div>
      </div>

      {/* Right: Cart */}
      <div className="w-full lg:w-80 xl:w-96 flex flex-col bg-white dark:bg-gray-800 rounded-xl sm:rounded-2xl border border-gray-200 dark:border-gray-700 shadow-sm min-h-0 max-h-[70vh] lg:max-h-full">
        {/* Cart header */}
        <div className="p-4 border-b border-gray-100 dark:border-gray-700 flex-shrink-0">
          <div className="flex items-center justify-between">
            <h2 className="font-bold text-gray-900 dark:text-white flex items-center gap-2">
              <ShoppingCart className="w-5 h-5 text-blue-500" />
              {language === 'fr' ? 'Panier' : 'Cart'}
              {cart.length > 0 ? (
                <span className="bg-blue-100 dark:bg-blue-900/30 text-blue-600 text-xs px-2 py-0.5 rounded-full font-bold">
                  {cart.reduce((s, i) => s + i.quantity, 0)}
                </span>
              ) : null}
            </h2>
            <div className="flex gap-2">
              {cart.length > 0 ? (
                <button onClick={() => setCart([])} className="text-xs text-red-500 hover:text-red-600">
                  {language === 'fr' ? 'Vider' : 'Clear'}
                </button>
              ) : null}
              <button onClick={resetData} className="text-xs text-gray-400 hover:text-gray-600">
                {language === 'fr' ? 'R├⌐initialiser' : 'Reset'}
              </button>
            </div>
          </div>

          {/* Client selector */}
          <div className="mt-3">
            {selectedClient ? (
              <div className="flex items-center justify-between bg-gray-50 dark:bg-gray-700/50 rounded-lg px-3 py-2">
                <div className="flex items-center gap-2">
                  <User className="w-4 h-4 text-gray-400" />
                  <span className="text-sm font-medium text-gray-700 dark:text-gray-300">{selectedClient.name}</span>
                </div>
                <button onClick={() => setSelectedClient(null)} className="text-gray-400 hover:text-red-500">
                  <X className="w-4 h-4" />
                </button>
              </div>
            ) : (
              <button
                onClick={() => setShowClientPicker(true)}
                className="w-full flex items-center gap-2 px-3 py-2 rounded-lg border border-dashed border-gray-300 dark:border-gray-600 text-sm text-gray-400 hover:border-blue-300 hover:text-blue-500 transition-colors"
              >
                <User className="w-4 h-4" />
                {language === 'fr' ? 'Ajouter client (optionnel)' : 'Add client (optional)'}
              </button>
            )}
          </div>
        </div>

        {/* Cart items */}
        <div className="flex-1 overflow-y-auto p-4 space-y-2 min-h-0">
          {cart.length === 0 ? (
            <div className="text-center text-gray-400 py-12">
              <ShoppingCart className="w-12 h-12 mx-auto mb-2 opacity-30" />
              <p className="text-sm">{language === 'fr' ? 'Panier vide' : 'Cart empty'}</p>
            </div>
          ) : (
            cart.map((item, idx) => (
              <div key={`${item.product.id}-${idx}`} className="flex items-center gap-3 p-2 rounded-lg bg-gray-50 dark:bg-gray-700/30">
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-gray-900 dark:text-white truncate">{item.product.name}</p>
                  {item.variant && <span className="text-xs font-semibold text-blue-500 bg-blue-50 dark:bg-blue-900/20 px-1.5 py-0.5 rounded">{item.variant}</span>}
                  {!item.variant && <p className="text-xs text-gray-400">{formatCurrency(item.product.sellingPrice)}</p>}
                </div>
                <div className="flex items-center gap-1">
                  <button onClick={() => updateQuantity(item.product.id, -1, item.variant)} className="w-7 h-7 rounded-lg bg-gray-200 dark:bg-gray-600 flex items-center justify-center hover:bg-gray-300 dark:hover:bg-gray-500 transition-colors">
                    <Minus className="w-3 h-3" />
                  </button>
                  <span className="w-8 text-center text-sm font-bold">{item.quantity}</span>
                  <button onClick={() => updateQuantity(item.product.id, 1, item.variant)} className="w-7 h-7 rounded-lg bg-gray-200 dark:bg-gray-600 flex items-center justify-center hover:bg-gray-300 dark:hover:bg-gray-500 transition-colors">
                    <Plus className="w-3 h-3" />
                  </button>
                </div>
                <div className="text-right w-20">
                  <p className="text-sm font-bold text-gray-900 dark:text-white">{formatCurrency(item.product.sellingPrice * item.quantity)}</p>
                </div>
                <button onClick={() => removeFromCart(item.product.id, item.variant)} className="text-red-400 hover:text-red-600 p-1">
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            ))
          )}
        </div>

        {/* Totals + Payment */}
        <div className="p-4 border-t border-gray-100 dark:border-gray-700 space-y-3 flex-shrink-0">
          <div className="space-y-1">
            <div className="flex justify-between text-sm text-gray-500">
              <span>{language === 'fr' ? 'Sous-total' : 'Subtotal'}</span>
              <span>{formatCurrency(subtotal)}</span>
            </div>
            <div className="flex items-center gap-2">
              <span className="text-sm text-gray-500">{language === 'fr' ? 'Remise' : 'Discount'}</span>
              <Input
                type="number" min={0} className="h-7 w-24 text-xs ml-auto text-right"
                value={discount === null || discount === undefined ? '' : discount} onChange={(e) => setDiscount(+e.target.value)}
              />
            </div>
            <div className="flex justify-between font-bold text-lg text-gray-900 dark:text-white pt-1 border-t border-gray-100 dark:border-gray-700">
              <span>Total</span>
              <span className="text-blue-600">{formatCurrency(total)}</span>
            </div>
          </div>

          {/* Payment method */}
          <div className="flex gap-2">
            {[
              { key: 'CASH' as const, icon: Banknote, label: language === 'fr' ? 'Esp├¿ces' : 'Cash' },
              { key: 'ORANGE_MONEY' as const, icon: Smartphone, label: 'OM' },
              { key: 'MTN_MOMO' as const, icon: Smartphone, label: 'MTN' },
              { key: 'BANK_TRANSFER' as const, icon: CreditCard, label: language === 'fr' ? 'Virement' : 'Transfer' },
            ].map(({ key, icon: Icon, label }) => (
              <button
                key={key}
                onClick={() => setPaymentMethod(key)}
                className={`flex-1 flex items-center justify-center gap-1 py-2 rounded-lg text-xs font-medium transition-all ${
                  paymentMethod === key
                    ? 'bg-blue-600 text-white shadow-sm'
                    : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600'
                }`}
              >
                <Icon className="w-3.5 h-3.5" /> {label}
              </button>
            ))}
          </div>

          {/* Amount paid */}
          <div>
            <label className="text-xs text-gray-500 mb-1 block">{language === 'fr' ? 'Montant re├ºu' : 'Amount received'}</label>
            <div className="flex gap-2">
              <Input
                type="number" min={0}
                value={amountPaid === null || amountPaid === undefined ? '' : amountPaid}
                onChange={(e) => setAmountPaid(+e.target.value)}
                className="flex-1"
              />
              <Button variant="outline" size="sm" onClick={() => setAmountPaid(total)}>
                {language === 'fr' ? 'Exact' : 'Exact'}
              </Button>
            </div>
            {change > 0 ? (
              <p className="text-xs text-green-600 mt-1 font-medium">
                {language === 'fr' ? 'Monnaie' : 'Change'}: {formatCurrency(change)}
              </p>
            ) : null}
          </div>

          {/* Checkout button */}
          <Button
            className="w-full h-12 text-base font-bold"
            disabled={cart.length === 0 || processing}
            onClick={handleCheckout}
          >
            {processing
              ? (language === 'fr' ? 'Traitement...' : 'Processing...')
              : (language === 'fr' ? `Valider la vente (${paymentStatus})` : `Complete sale (${paymentStatus})`)
            }
          </Button>
        </div>
      </div>

      {/* Client picker modal */}
      {renderClientPicker()}

      {/* Scanner */}
      {showScanner ? (
        <BarcodeScanner onScan={handleBarcodeScan} onClose={() => setShowScanner(false)} />
      ) : null}

      {/* Variant / Size picker */}
      {variantPicker ? (
        <div className="fixed inset-0 z-[100] bg-black/60 flex items-center justify-center p-4">
          <Card className="w-full max-w-sm shadow-2xl">
            <CardContent className="p-4">
              <div className="flex items-center justify-between mb-4">
                <h3 className="font-bold">{variantPicker.product.name}</h3>
                <button onClick={() => setVariantPicker(null)} className="p-1 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg"><X className="w-5 h-5" /></button>
              </div>
              <p className="text-sm text-gray-500 mb-3">{language === 'fr' ? 'Choisir la taille :' : 'Choose size:'}</p>
              <div className="grid grid-cols-3 gap-2">
                {variantPicker.sizes.map((sizeEntry) => {
                  const [size, qty] = sizeEntry.split(':');
                  const available = parseInt(qty, 10) || 0;
                  return (
                    <button
                      key={size}
                      disabled={available <= 0}
                      onClick={() => addToCart(variantPicker.product, size.trim())}
                      className={`p-3 rounded-xl border-2 text-center transition-all ${
                        available <= 0
                          ? 'opacity-40 cursor-not-allowed border-gray-200 bg-gray-50'
                          : 'border-blue-200 hover:border-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 cursor-pointer'
                      }`}
                    >
                      <div className="font-bold text-sm">{size.trim()}</div>
                      <div className={`text-xs mt-0.5 ${available <= 3 ? 'text-orange-500 font-semibold' : 'text-gray-400'}`}>{available} {language === 'fr' ? 'dispo' : 'left'}</div>
                    </button>
                  );
                })}
              </div>
            </CardContent>
          </Card>
        </div>
      ) : null}

      {/* Invoice modal after checkout */}
      {showInvoice && completedInvoice ? (
        <InvoiceModal
          invoice={completedInvoice as Parameters<typeof InvoiceModal>[0]['invoice']}
          onClose={() => { setShowInvoice(false); setCompletedInvoice(null); }}
        />
      ) : null}

      {/* Success toast (fallback when no invoice) */}
      {showSuccess ? (
        <div className="fixed top-4 right-4 z-50 bg-green-600 text-white px-6 py-3 rounded-xl shadow-lg animate-in fade-in slide-in-from-top-2">
          <p className="font-bold">{language === 'fr' ? 'Vente enregistr├⌐e !' : 'Sale recorded!'}</p>
        </div>
      ) : null}
    </div>
  );
}

