import { useEffect, useState, useCallback } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { useTranslation } from '@/i18n/useTranslation';
import { useAuthStore } from '@/stores/authStore';
import { formatCurrency } from '@/lib/utils';
import { Plus, Search, Package, Pencil, Trash2, X, ScanLine, Download, ChevronLeft, ChevronRight } from 'lucide-react';
import { BarcodeScanner } from '@/components/BarcodeScanner';
import { ImageUpload } from '@/components/ImageUpload';
import api from '@/lib/api';
import { cn } from '@/lib/utils';

interface Product {
  id: string;
  name: string;
  businessType: string;
  costPrice: number;
  sellingPrice: number;
  totalStock: number;
  lowStockAlert: number;
  isActive: boolean;
  image?: string;
  adaptiveFields?: Record<string, unknown>;
  category?: { id: string; name: string } | null;
}

const ADAPTIVE_FIELDS: Record<string, { label: string; labelEn: string; fields: string[] }> = {
  CLOTHING: { label: 'V├¬tements', labelEn: 'Clothing', fields: ['color', 'sizes'] },
  SHOES: { label: 'Chaussures', labelEn: 'Shoes', fields: ['brand', 'color', 'sizes'] },
  PERFUMES: { label: 'Parfums', labelEn: 'Perfumes', fields: ['brand', 'volume'] },
  COSMETICS: { label: 'Cosm├⌐tiques', labelEn: 'Cosmetics', fields: ['brand', 'type'] },
  HIJABS_ABAYAS: { label: 'Hijabs/Abayas', labelEn: 'Hijabs/Abayas', fields: ['color', 'sizes'] },
  JEWELRY: { label: 'Bijoux', labelEn: 'Jewelry', fields: ['material', 'type'] },
  BAGS: { label: 'Sacs', labelEn: 'Bags', fields: ['brand', 'color', 'material'] },
  ELECTRONICS: { label: '├ëlectronique', labelEn: 'Electronics', fields: ['brand', 'model', 'warranty'] },
  HOUSE_PRODUCTS: { label: 'Maison', labelEn: 'House', fields: ['type', 'material'] },
  KITCHEN_PRODUCTS: { label: 'Cuisine', labelEn: 'Kitchen', fields: ['type', 'material'] },
  DECORATION: { label: 'D├⌐coration', labelEn: 'Decoration', fields: ['type', 'color'] },
  MINI_MARKET: { label: 'Mini Market', labelEn: 'Mini Market', fields: ['brand', 'weight'] },
  WHOLESALE: { label: 'Grossiste', labelEn: 'Wholesale', fields: ['brand', 'minQuantity'] },
  MIXED_SHOP: { label: 'Boutique Mixte', labelEn: 'Mixed Shop', fields: ['type'] },
  CAKES: { label: 'G├óteaux', labelEn: 'Cakes', fields: ['flavors', 'sizes'] },
  FOOD_BUSINESS: { label: 'Food Business', labelEn: 'Food Business', fields: ['portions'] },
  FOOD_DELIVERY: { label: 'Food Delivery', labelEn: 'Food Delivery', fields: ['portions', 'deliveryZone'] },
  HOME_COOKING: { label: 'Cuisine Maison', labelEn: 'Home Cooking', fields: ['portions'] },
  WHATSAPP_SELLER: { label: 'Vendeur WhatsApp', labelEn: 'WhatsApp Seller', fields: ['color', 'sizes'] },
  MADE_TO_ORDER: { label: 'Sur Commande', labelEn: 'Made to Order', fields: ['measurements'] },
  OTHER: { label: 'Autre', labelEn: 'Other', fields: [] },
};

// Business types made on order ΓÇö no stock to track
const ORDER_BASED_TYPES = new Set([
  'CAKES', 'FOOD_BUSINESS', 'FOOD_DELIVERY', 'HOME_COOKING', 'MADE_TO_ORDER',
]);

// Translated labels for adaptive fields (FR / EN)
const FIELD_LABELS: Record<string, { fr: string; en: string; placeholder?: string }> = {
  color: { fr: 'Couleur', en: 'Color' },
  sizes: { fr: 'Tailles & quantit├⌐s', en: 'Sizes & quantities', placeholder: 'Ex: S:5, M:10, L:7' },
  brand: { fr: 'Marque', en: 'Brand' },
  volume: { fr: 'Volume', en: 'Volume', placeholder: 'Ex: 50ml, 100ml' },
  type: { fr: 'Type', en: 'Type' },
  material: { fr: 'Mati├¿re', en: 'Material' },
  model: { fr: 'Mod├¿le', en: 'Model' },
  warranty: { fr: 'Garantie', en: 'Warranty', placeholder: 'Ex: 6 mois, 1 an' },
  weight: { fr: 'Poids', en: 'Weight', placeholder: 'Ex: 1kg, 500g' },
  minQuantity: { fr: 'Quantit├⌐ minimale', en: 'Minimum quantity' },
  flavors: { fr: 'Parfums / Saveurs', en: 'Flavors', placeholder: 'Ex: Vanille, Chocolat, Fraise' },
  portions: { fr: 'Portions', en: 'Portions', placeholder: 'Ex: 1 personne, 4 personnes' },
  deliveryZone: { fr: 'Zone de livraison', en: 'Delivery zone', placeholder: 'Ex: Akwa, Bonapriso' },
  measurements: { fr: 'Mesures', en: 'Measurements', placeholder: 'Ex: tour de taille, longueur' },
};

const defaultForm = {
  name: '', businessType: 'OTHER', costPrice: 0, sellingPrice: 0,
  totalStock: 0, lowStockAlert: 5, categoryId: null as string | null,
  adaptiveFields: {} as Record<string, unknown>,
  image: '' as string,
};

export function ProductsPage() {
  const { t, language } = useTranslation();
  const tenant = useAuthStore((s) => s.tenant);
  const [products, setProducts] = useState<Product[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [total, setTotal] = useState(0);
  const PAGE_SIZE = 20;
  const [showForm, setShowForm] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState(defaultForm);
  const [formImage, setFormImage] = useState('');

  const fetchProducts = useCallback(async () => {
    try {
      const { data } = await api.get('/products', { params: { search, limit: PAGE_SIZE, page } });
      setProducts(data.data);
      const totalCount = data.pagination?.total || data.data.length;
      setTotal(totalCount);
      setTotalPages(Math.max(1, Math.ceil(totalCount / PAGE_SIZE)));
    } catch (err) { console.error(err); }
    finally { setLoading(false); }
  }, [search, page]);

  useEffect(() => { fetchProducts(); }, [fetchProducts]);
  useEffect(() => { setPage(1); }, [search]);

  // Auto-calculate totalStock from sizes for HIJABS_ABAYAS
  useEffect(() => {
    if (form.businessType === 'HIJABS_ABAYAS' && form.adaptiveFields.sizes) {
      const sizesStr = form.adaptiveFields.sizes as string;
      const total = sizesStr.split(',').reduce((sum, part) => {
        const match = part.trim().match(/(\d+)$/);
        return sum + (match ? parseInt(match[1], 10) : 0);
      }, 0);
      setForm(prev => ({ ...prev, totalStock: total }));
    }
  }, [form.businessType, form.adaptiveFields.sizes]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const payload = { ...form, image: formImage };
      if (editingId) {
        await api.put(`/products/${editingId}`, payload);
      } else {
        await api.post('/products', payload);
      }
      setShowForm(false);
      setEditingId(null);
      setForm(defaultForm);
      setFormImage('');
      fetchProducts();
    } catch (err) { console.error(err); }
  };

  const handleEdit = (product: Product) => {
    setForm({
      name: product.name,
      businessType: product.businessType,
      costPrice: product.costPrice,
      sellingPrice: product.sellingPrice,
      totalStock: product.totalStock,
      lowStockAlert: product.lowStockAlert,
      categoryId: product.category?.id ?? null,
      adaptiveFields: (product.adaptiveFields || {}) as Record<string, unknown>,
      image: product.image || '',
    });
    setFormImage(product.image || '');
    setEditingId(product.id);
    setShowForm(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm(t('common.confirm') + '?')) return;
    try {
      await api.delete(`/products/${id}`);
      fetchProducts();
    } catch (err) { console.error(err); }
  };

  const handleBarcodeScan = async (code: string) => {
    try {
      const { data } = await api.get(`/products/barcode/${code}`);
      if (data.data) {
        handleEdit(data.data);
        setShowScanner(false);
      }
    } catch {
      alert('Produit non trouv├⌐ pour ce code');
    }
  };

  const handleExport = async () => {
    try {
      const res = await api.get('/exports/products', { responseType: 'blob' });
      const url = URL.createObjectURL(res.data);
      const a = document.createElement('a');
      a.href = url;
      a.download = `produits-${Date.now()}.csv`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error(err);
    }
  };

  const businessTypes = tenant?.businessCategories || ['OTHER'];
  const canScan = tenant?.plan === 'SHOP' || tenant?.plan === 'BUSINESS';

  return (
    <div className="space-y-4 sm:space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
        <h1 className="text-xl sm:text-2xl font-bold">{t('products.title')}</h1>
        <div className="flex gap-2 flex-wrap">
          <Button variant="outline" size="sm" onClick={handleExport}>
            <Download className="w-4 h-4 mr-1" /> <span className="hidden sm:inline">CSV</span>
          </Button>
          {canScan && (
            <Button variant="outline" size="sm" onClick={() => setShowScanner(true)}>
              <ScanLine className="w-4 h-4 mr-1" /> <span className="hidden sm:inline">Scanner</span>
            </Button>
          )}
          <Button size="sm" onClick={() => { setForm(defaultForm); setFormImage(''); setEditingId(null); setShowForm(true); }}>
            <Plus className="w-4 h-4 mr-1" /> {t('products.addProduct')}
          </Button>
        </div>
      </div>

      {/* Search */}
      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
        <Input
          className="pl-9 max-w-full sm:max-w-md"
          placeholder={t('common.search')}
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </div>

      {/* Form Modal */}
      {showForm && (
        <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4">
          <Card className="w-full max-w-lg max-h-[90vh] overflow-y-auto">
            <CardHeader className="flex flex-row items-center justify-between">
              <CardTitle>{editingId ? t('common.edit') : t('products.addProduct')}</CardTitle>
              <Button variant="ghost" size="icon" onClick={() => setShowForm(false)}><X className="w-4 h-4" /></Button>
            </CardHeader>
            <CardContent>
              <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                  <label className="text-sm font-medium mb-1 block">{t('products.name')}</label>
                  <Input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} required />
                </div>

                <ImageUpload
                  value={formImage}
                  onChange={setFormImage}
                  label={language === 'fr' ? 'Image du produit' : 'Product image'}
                />

                <div>
                  <label className="text-sm font-medium mb-1 block">{t('products.category')}</label>
                  <div className="flex flex-wrap gap-2">
                    {businessTypes.map((bt) => (
                      <button key={bt} type="button"
                        onClick={() => setForm({ ...form, businessType: bt })}
                        className={cn('px-3 py-1.5 rounded-full text-xs font-medium border transition-all cursor-pointer',
                          form.businessType === bt ? 'bg-blue-600 text-white border-blue-600' : 'border-border hover:border-blue-300'
                        )}>
                        {ADAPTIVE_FIELDS[bt]?.label || bt}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-sm font-medium mb-1 block">{t('products.costPrice')} (FCFA)</label>
                    <Input type="number" placeholder="0" value={form.costPrice === null || form.costPrice === undefined ? '' : form.costPrice} onChange={(e) => setForm({ ...form, costPrice: e.target.value ? +e.target.value : 0 })} />
                  </div>
                  <div>
                    <label className="text-sm font-medium mb-1 block">{t('products.sellingPrice')} (FCFA)</label>
                    <Input type="number" placeholder="0" value={form.sellingPrice === null || form.sellingPrice === undefined ? '' : form.sellingPrice} onChange={(e) => setForm({ ...form, sellingPrice: e.target.value ? +e.target.value : 0 })} />
                  </div>
                </div>

                {ORDER_BASED_TYPES.has(form.businessType) ? (
                  <p className="text-xs text-muted-foreground bg-amber-50 dark:bg-amber-900/20 rounded-lg px-3 py-2">
                    {language === 'fr'
                      ? 'Produit fait sur commande ΓÇö pas de gestion de stock. La date de livraison se d├⌐finit lors de la commande.'
                      : 'Made-to-order product ΓÇö no stock tracking. Delivery date is set when the order is placed.'}
                  </p>
                ) : (
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="text-sm font-medium mb-1 block">{t('products.stock')}</label>
                      {form.businessType === 'HIJABS_ABAYAS' ? (
                        <Input
                          type="number"
                          placeholder={t('products.autoCalculated')}
                          value={form.totalStock === null || form.totalStock === undefined ? '' : form.totalStock}
                          readOnly
                          className="bg-gray-50"
                        />
                      ) : (
                        <Input type="number" placeholder="0" value={form.totalStock === null || form.totalStock === undefined ? '' : form.totalStock} onChange={(e) => setForm({ ...form, totalStock: e.target.value ? +e.target.value : 0 })} />
                      )}
                    </div>
                    <div>
                      <label className="text-sm font-medium mb-1 block">{t('products.lowStock')}</label>
                      <Input type="number" placeholder="5" value={form.lowStockAlert === null || form.lowStockAlert === undefined ? '' : form.lowStockAlert} onChange={(e) => setForm({ ...form, lowStockAlert: e.target.value ? +e.target.value : 5 })} />
                    </div>
                  </div>
                )}

                {/* Adaptive Fields */}
                {form.businessType && ADAPTIVE_FIELDS[form.businessType]?.fields.map((field) => {
                  const meta = FIELD_LABELS[field];
                  const label = meta ? (language === 'fr' ? meta.fr : meta.en) : field;
                  return (
                    <div key={field}>
                      <label className="text-sm font-medium mb-1 block">{label}</label>
                      <Input
                        placeholder={meta?.placeholder || ''}
                        value={typeof form.adaptiveFields[field] === 'string' ? form.adaptiveFields[field] as string : ''}
                        onChange={(e) => setForm({ ...form, adaptiveFields: { ...form.adaptiveFields, [field]: e.target.value } })}
                      />
                    </div>
                  );
                })}

                <div className="flex gap-3 pt-2">
                  <Button type="button" variant="outline" onClick={() => setShowForm(false)} className="flex-1">
                    {t('common.cancel')}
                  </Button>
                  <Button type="submit" className="flex-1">
                    {t('common.save')}
                  </Button>
                </div>
              </form>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Products Grid */}
      {loading ? (
        <div className="flex justify-center py-12">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-kabrak-500" />
        </div>
      ) : products.length === 0 ? (
        <div className="text-center py-12">
          <Package className="w-16 h-16 mx-auto text-muted-foreground/50 mb-4" />
          <p className="text-muted-foreground">{t('common.noResults')}</p>
        </div>
      ) : (
        <>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3 sm:gap-4">
            {products.map((product) => (
              <Card key={product.id} className="hover:shadow-md transition-shadow overflow-hidden">
                {product.image ? (
                  <div className="w-full h-32 bg-gray-100 dark:bg-gray-800 overflow-hidden">
                    <img src={product.image} alt={product.name} className="w-full h-full object-cover" />
                  </div>
                ) : (
                  <div className="w-full h-32 bg-gray-100 dark:bg-gray-800 flex items-center justify-center">
                    <Package className="w-10 h-10 text-muted-foreground/30" />
                  </div>
                )}
                <CardContent className="p-3 sm:p-4">
                  <div className="flex items-start justify-between mb-2 sm:mb-3">
                    <div className="min-w-0 flex-1 mr-2">
                      <h3 className="font-semibold text-sm truncate">{product.name}</h3>
                      <p className="text-xs text-muted-foreground">{ADAPTIVE_FIELDS[product.businessType]?.label || product.businessType}</p>
                    </div>
                    <Badge variant={product.totalStock <= product.lowStockAlert ? 'warning' : 'secondary'} className="shrink-0 text-xs">
                      {product.totalStock}
                    </Badge>
                  </div>

                  <div className="flex items-center justify-between mb-2 sm:mb-3">
                    <div>
                      <p className="text-[10px] sm:text-xs text-muted-foreground">{t('products.costPrice')}</p>
                      <p className="text-xs sm:text-sm">{formatCurrency(product.costPrice)}</p>
                    </div>
                    <div className="text-right">
                      <p className="text-[10px] sm:text-xs text-muted-foreground">{t('products.sellingPrice')}</p>
                      <p className="text-xs sm:text-sm font-bold text-blue-600">{formatCurrency(product.sellingPrice)}</p>
                    </div>
                  </div>

                  <div className="flex gap-2">
                    <Button variant="outline" size="sm" className="flex-1 h-8 text-xs" onClick={() => handleEdit(product)}>
                      <Pencil className="w-3 h-3 mr-1" /> {t('common.edit')}
                    </Button>
                    <Button variant="outline" size="sm" className="h-8 text-destructive hover:text-destructive" onClick={() => handleDelete(product.id)}>
                      <Trash2 className="w-3 h-3" />
                    </Button>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>

          {/* Pagination */}
          {totalPages > 1 && (
            <div className="flex items-center justify-center gap-2 pt-4">
              <Button
                variant="outline"
                size="sm"
                disabled={page <= 1}
                onClick={() => setPage(p => Math.max(1, p - 1))}
              >
                <ChevronLeft className="w-4 h-4" />
              </Button>
              <span className="text-sm text-muted-foreground">
                {page} / {totalPages} ({total})
              </span>
              <Button
                variant="outline"
                size="sm"
                disabled={page >= totalPages}
                onClick={() => setPage(p => Math.min(totalPages, p + 1))}
              >
                <ChevronRight className="w-4 h-4" />
              </Button>
            </div>
          )}
        </>
      )}

      {/* Barcode Scanner */}
      {showScanner && (
        <BarcodeScanner
          onScan={handleBarcodeScan}
          onClose={() => setShowScanner(false)}
        />
      )}
    </div>
  );
}

