import { useState, useEffect, useCallback } from 'react';
import { useTranslation } from '@/i18n/useTranslation';
import api from '@/lib/api';
import { formatCurrency } from '@/lib/utils';
import { RefreshCw, Plus, Trash2, X } from 'lucide-react';
import { cn } from '@/lib/utils';

interface RecurringBilling {
  id: string;
  amount: number;
  frequency: string;
  nextBillingDate: string;
  isActive: boolean;
  client: { id: string; name: string } | null;
  product: { id: string; name: string } | null;
}

interface Client {
  id: string;
  name: string;
}

interface ServiceProduct {
  id: string;
  name: string;
  sellingPrice: number;
}

export function RecurringPage() {
  const { t, language } = useTranslation();
  const [items, setItems] = useState<RecurringBilling[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [clients, setClients] = useState<Client[]>([]);
  const [services, setServices] = useState<ServiceProduct[]>([]);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({
    clientId: '',
    productId: '',
    amount: 0,
    frequency: 'monthly',
    nextBillingDate: '',
  });

  const fetchItems = useCallback(async () => {
    try {
      const { data } = await api.get('/recurring');
      setItems(data.data);
    } catch { /* ignore */ }
    setLoading(false);
  }, []);

  useEffect(() => { fetchItems(); }, [fetchItems]);

  useEffect(() => {
    if (showForm) {
      api.get('/clients?limit=200').then(({ data }) => setClients(data.data || [])).catch(() => {});
      api.get('/products?isService=true&limit=200').then(({ data }) => {
        setServices((data.data || []).filter((p: { isService: boolean }) => p.isService));
      }).catch(() => {});
    }
  }, [showForm]);

  const handleToggle = async (item: RecurringBilling) => {
    try {
      await api.put(`/recurring/${item.id}`, { isActive: !item.isActive });
      fetchItems();
    } catch { /* ignore */ }
  };

  const handleDelete = async (id: string) => {
    if (!confirm(language === 'fr' ? 'Supprimer ?' : 'Delete?')) return;
    try {
      await api.delete(`/recurring/${id}`);
      fetchItems();
    } catch { /* ignore */ }
  };

  const handleCreate = async () => {
    if (!form.clientId || !form.amount || !form.nextBillingDate) return;
    setSaving(true);
    try {
      await api.post('/recurring', {
        clientId: form.clientId,
        productId: form.productId || undefined,
        amount: form.amount,
        frequency: form.frequency,
        nextBillingDate: form.nextBillingDate,
      });
      setShowForm(false);
      setForm({ clientId: '', productId: '', amount: 0, frequency: 'monthly', nextBillingDate: '' });
      fetchItems();
    } catch { /* ignore */ }
    setSaving(false);
  };

  const handleServiceSelect = (productId: string) => {
    setForm((prev) => {
      const svc = services.find((s) => s.id === productId);
      return { ...prev, productId, amount: svc ? svc.sellingPrice : prev.amount };
    });
  };

  const formatDate = (d: string) => new Date(d).toLocaleDateString(language === 'fr' ? 'fr-FR' : 'en-US');

  const FREQ_LABELS: Record<string, Record<string, string>> = {
    fr: { weekly: 'Hebdomadaire', monthly: 'Mensuel', quarterly: 'Trimestriel', yearly: 'Annuel' },
    en: { weekly: 'Weekly', monthly: 'Monthly', quarterly: 'Quarterly', yearly: 'Yearly' },
  };

  const FREQ_OPTIONS = [
    { value: 'weekly', label: language === 'fr' ? 'Hebdomadaire' : 'Weekly' },
    { value: 'monthly', label: language === 'fr' ? 'Mensuel' : 'Monthly' },
    { value: 'quarterly', label: language === 'fr' ? 'Trimestriel' : 'Quarterly' },
    { value: 'yearly', label: language === 'fr' ? 'Annuel' : 'Yearly' },
  ];

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <RefreshCw className="w-6 h-6 text-violet-600" />
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">{t('recurring.title')}</h1>
        </div>
        <button
          onClick={() => setShowForm(!showForm)}
          className="flex items-center gap-2 px-4 py-2.5 bg-violet-600 text-white rounded-xl text-sm font-medium hover:bg-violet-700 transition-colors"
        >
          <Plus className="w-4 h-4" /> {t('recurring.addRecurring')}
        </button>
      </div>

      {/* Creation form */}
      {showForm && (
        <div className="bg-white dark:bg-gray-800 rounded-xl p-6 border-2 border-violet-200 dark:border-violet-800 space-y-4">
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-semibold dark:text-white">
              {language === 'fr' ? 'Nouvelle facturation r├⌐currente' : 'New Recurring Billing'}
            </h2>
            <button onClick={() => setShowForm(false)} className="p-1 rounded hover:bg-gray-100 dark:hover:bg-gray-700">
              <X className="w-5 h-5 text-gray-400" />
            </button>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                {language === 'fr' ? 'Client *' : 'Client *'}
              </label>
              <select
                value={form.clientId}
                onChange={(e) => setForm({ ...form, clientId: e.target.value })}
                className="w-full border border-gray-200 dark:border-gray-600 rounded-xl px-4 py-2.5 text-sm bg-gray-50 dark:bg-gray-700 dark:text-white"
              >
                <option value="">{language === 'fr' ? '-- S├⌐lectionner --' : '-- Select --'}</option>
                {clients.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                {language === 'fr' ? 'Service (optionnel)' : 'Service (optional)'}
              </label>
              <select
                value={form.productId}
                onChange={(e) => handleServiceSelect(e.target.value)}
                className="w-full border border-gray-200 dark:border-gray-600 rounded-xl px-4 py-2.5 text-sm bg-gray-50 dark:bg-gray-700 dark:text-white"
              >
                <option value="">{language === 'fr' ? '-- Aucun --' : '-- None --'}</option>
                {services.map((s) => <option key={s.id} value={s.id}>{s.name} ({formatCurrency(s.sellingPrice)})</option>)}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                {language === 'fr' ? 'Montant (FCFA) *' : 'Amount (FCFA) *'}
              </label>
              <input
                type="number"
                value={form.amount === null || form.amount === undefined ? '' : form.amount}
                onChange={(e) => setForm({ ...form, amount: parseFloat(e.target.value) || 0 })}
                className="w-full border border-gray-200 dark:border-gray-600 rounded-xl px-4 py-2.5 text-sm bg-gray-50 dark:bg-gray-700 dark:text-white"
                placeholder="75000"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                {language === 'fr' ? 'Fr├⌐quence' : 'Frequency'}
              </label>
              <select
                value={form.frequency}
                onChange={(e) => setForm({ ...form, frequency: e.target.value })}
                className="w-full border border-gray-200 dark:border-gray-600 rounded-xl px-4 py-2.5 text-sm bg-gray-50 dark:bg-gray-700 dark:text-white"
              >
                {FREQ_OPTIONS.map((f) => <option key={f.value} value={f.value}>{f.label}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                {language === 'fr' ? 'Prochaine facturation *' : 'Next billing date *'}
              </label>
              <input
                type="date"
                value={form.nextBillingDate}
                onChange={(e) => setForm({ ...form, nextBillingDate: e.target.value })}
                className="w-full border border-gray-200 dark:border-gray-600 rounded-xl px-4 py-2.5 text-sm bg-gray-50 dark:bg-gray-700 dark:text-white"
              />
            </div>
          </div>
          <div className="flex gap-3 pt-2">
            <button onClick={() => setShowForm(false)} className="px-4 py-2.5 border border-gray-200 dark:border-gray-600 rounded-xl text-sm text-gray-600 dark:text-gray-300">
              {t('common.cancel')}
            </button>
            <button
              onClick={handleCreate}
              disabled={saving || !form.clientId || !form.amount || !form.nextBillingDate}
              className="px-6 py-2.5 bg-violet-600 text-white rounded-xl text-sm font-medium hover:bg-violet-700 disabled:opacity-50 transition-colors"
            >
              {saving ? '...' : (language === 'fr' ? 'Cr├⌐er' : 'Create')}
            </button>
          </div>
        </div>
      )}

      {loading ? (
        <div className="text-center py-12 text-gray-400">{t('common.loading')}</div>
      ) : items.length === 0 ? (
        <div className="text-center py-12">
          <RefreshCw className="w-12 h-12 text-gray-300 mx-auto mb-3" />
          <p className="text-gray-400">{language === 'fr' ? 'Aucune facturation r├⌐currente' : 'No recurring billing'}</p>
          <button
            onClick={() => setShowForm(true)}
            className="mt-4 px-4 py-2 bg-violet-600 text-white rounded-xl text-sm font-medium hover:bg-violet-700"
          >
            <Plus className="w-4 h-4 inline mr-1" /> {language === 'fr' ? 'Cr├⌐er la premi├¿re' : 'Create first one'}
          </button>
        </div>
      ) : (
        <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 overflow-hidden">
          <table className="w-full text-sm">
            <thead className="bg-gray-50 dark:bg-gray-700 text-gray-500 dark:text-gray-400 text-xs uppercase">
              <tr>
                <th className="px-4 py-3 text-left">{t('clients.name')}</th>
                <th className="px-4 py-3 text-left">{language === 'fr' ? 'Service' : 'Service'}</th>
                <th className="px-4 py-3 text-right">{t('recurring.amount')}</th>
                <th className="px-4 py-3 text-center">{t('recurring.frequency')}</th>
                <th className="px-4 py-3 text-center">{t('recurring.nextBilling')}</th>
                <th className="px-4 py-3 text-center">{t('common.status')}</th>
                <th className="px-4 py-3 text-center">{t('common.actions')}</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
              {items.map((item) => (
                <tr key={item.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50">
                  <td className="px-4 py-3 font-medium text-gray-900 dark:text-white">{item.client?.name || 'ΓÇö'}</td>
                  <td className="px-4 py-3 text-gray-500 dark:text-gray-400">{item.product?.name || 'ΓÇö'}</td>
                  <td className="px-4 py-3 text-right font-semibold text-gray-900 dark:text-white">{formatCurrency(item.amount)}</td>
                  <td className="px-4 py-3 text-center">
                    <span className="text-xs bg-violet-50 dark:bg-violet-900/20 text-violet-600 px-2 py-1 rounded-full">
                      {FREQ_LABELS[language]?.[item.frequency] || item.frequency}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-center text-gray-500 dark:text-gray-400">{formatDate(item.nextBillingDate)}</td>
                  <td className="px-4 py-3 text-center">
                    <button
                      onClick={() => handleToggle(item)}
                      className={cn(
                        'text-xs px-2.5 py-1 rounded-full font-medium cursor-pointer',
                        item.isActive ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-500'
                      )}
                    >
                      {item.isActive ? (language === 'fr' ? 'Actif' : 'Active') : (language === 'fr' ? 'Inactif' : 'Inactive')}
                    </button>
                  </td>
                  <td className="px-4 py-3 text-center">
                    <button onClick={() => handleDelete(item.id)} className="p-1.5 text-gray-400 hover:text-red-600 rounded-lg hover:bg-red-50 dark:hover:bg-red-900/20">
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { useTranslation } from '@/i18n/useTranslation';
import { useAuthStore } from '@/stores/authStore';
import { formatCurrency } from '@/lib/utils';
import { BarChart3, TrendingUp, DollarSign, ShoppingCart, Download, FolderKanban, FileText } from 'lucide-react';
import { Button } from '@/components/ui/button';
import api from '@/lib/api';

interface SalesReport {
  totalRevenue: number;
  totalProfit: number;
  totalOrders: number;
  salesByPeriod: Array<{ period: string; revenue: number; orders: number; profit: number }>;
  topSellers: Array<{ name: string; revenue: number; orders: number }>;
}

interface ServiceReport {
  totalProjects: number;
  activeProjects: number;
  totalRevenue: number;
  totalPending: number;
  projects: Array<{
    id: string; name: string; status: string; totalBudget: number;
    amountPaid: number; amountRemaining: number;
    client?: { name: string } | null;
  }>;
}

export function ReportsPage() {
  const { t, language } = useTranslation();
  const tenant = useAuthStore((s) => s.tenant);
  const businessMode = tenant?.businessMode || 'PRODUCT';
  const [report, setReport] = useState<SalesReport | null>(null);
  const [serviceReport, setServiceReport] = useState<ServiceReport | null>(null);
  const [loading, setLoading] = useState(true);
  const [period, setPeriod] = useState<'day' | 'week' | 'month'>('day');
  const [customRange, setCustomRange] = useState<{ from: string; to: string } | null>(null);

  const fetchReport = () => {
    if (businessMode === 'SERVICE') {
      api.get('/projects')
        .then((res) => {
          const projects = res.data.data || [];
          const active = projects.filter((p: { status: string }) => p.status === 'ACTIVE');
          const totalRevenue = projects.reduce((s: number, p: { amountPaid: number }) => s + (p.amountPaid || 0), 0);
          const totalPending = projects.reduce((s: number, p: { amountRemaining: number }) => s + (p.amountRemaining || 0), 0);
          setServiceReport({ totalProjects: projects.length, activeProjects: active.length, totalRevenue, totalPending, projects });
        })
        .catch(console.error)
        .finally(() => setLoading(false));
    } else {
      const params: any = { groupBy: period };
      if (customRange) {
        params.from = customRange.from;
        params.to = customRange.to;
      }
      api.get('/reports/sales', { params })
        .then((res) => setReport(res.data.data))
        .catch(console.error)
        .finally(() => setLoading(false));
    }
  };

  useEffect(() => {
    fetchReport();
  }, [businessMode, period, customRange]);

  const exportData = async (type: string) => {
    try {
      const res = await api.get(`/exports/${type}`, { responseType: 'blob' });
      const url = URL.createObjectURL(res.data);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${type}-${Date.now()}.csv`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error(err);
    }
  };

  if (loading) {
    return <div className="flex justify-center py-12"><div className="animate-spin rounded-full h-12 w-12 border-b-2 border-kabrak-500" /></div>;
  }

  if (businessMode === 'SERVICE') {
    return (
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <h1 className="text-2xl font-bold dark:text-white">{t('nav.reports')}</h1>
          <Button variant="outline" size="sm" onClick={() => exportData('clients')}>
            <Download className="w-4 h-4 mr-1" /> Clients
          </Button>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          <Card className="border-l-4 border-l-violet-500">
            <CardContent className="p-4 flex items-center gap-4">
              <div className="w-12 h-12 rounded-full bg-violet-100 dark:bg-violet-900/30 flex items-center justify-center">
                <FolderKanban className="w-6 h-6 text-violet-500" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">{language === 'fr' ? 'Total Projets' : 'Total Projects'}</p>
                <p className="text-2xl font-bold dark:text-white">{serviceReport?.totalProjects || 0}</p>
              </div>
            </CardContent>
          </Card>
          <Card className="border-l-4 border-l-blue-500">
            <CardContent className="p-4 flex items-center gap-4">
              <div className="w-12 h-12 rounded-full bg-blue-100 dark:bg-blue-900/30 flex items-center justify-center">
                <FolderKanban className="w-6 h-6 text-blue-500" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">{language === 'fr' ? 'Projets Actifs' : 'Active Projects'}</p>
                <p className="text-2xl font-bold dark:text-white">{serviceReport?.activeProjects || 0}</p>
              </div>
            </CardContent>
          </Card>
          <Card className="border-l-4 border-l-green-500">
            <CardContent className="p-4 flex items-center gap-4">
              <div className="w-12 h-12 rounded-full bg-green-100 dark:bg-green-900/30 flex items-center justify-center">
                <DollarSign className="w-6 h-6 text-green-500" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">{language === 'fr' ? 'Revenus Re├ºus' : 'Revenue Received'}</p>
                <p className="text-2xl font-bold dark:text-white">{formatCurrency(serviceReport?.totalRevenue || 0)}</p>
              </div>
            </CardContent>
          </Card>
          <Card className="border-l-4 border-l-amber-500">
            <CardContent className="p-4 flex items-center gap-4">
              <div className="w-12 h-12 rounded-full bg-amber-100 dark:bg-amber-900/30 flex items-center justify-center">
                <FileText className="w-6 h-6 text-amber-500" />
              </div>
              <div>
                <p className="text-sm text-muted-foreground">{language === 'fr' ? 'Paiements en Attente' : 'Pending Payments'}</p>
                <p className="text-2xl font-bold dark:text-white">{formatCurrency(serviceReport?.totalPending || 0)}</p>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Projects list */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2 dark:text-white">
              <FolderKanban className="w-5 h-5 text-violet-500" />
              {language === 'fr' ? 'Tous les projets' : 'All Projects'}
            </CardTitle>
          </CardHeader>
          <CardContent>
            {serviceReport?.projects?.length ? (
              <div className="space-y-2">
                {serviceReport.projects.map((project) => (
                  <div key={project.id} className="flex items-center justify-between p-3 bg-muted/50 rounded-lg">
                    <div>
                      <p className="font-medium dark:text-white">{project.name}</p>
                      <p className="text-xs text-muted-foreground">
                        {project.client?.name || (language === 'fr' ? 'Pas de client' : 'No client')}
                      </p>
                    </div>
                    <div className="text-right">
                      <p className="font-bold dark:text-white">{formatCurrency(project.totalBudget)}</p>
                      <div className="flex gap-2 text-xs">
                        <span className="text-green-600">{language === 'fr' ? 'Re├ºu' : 'Paid'}: {formatCurrency(project.amountPaid)}</span>
                        <span className="text-amber-600">{language === 'fr' ? 'Reste' : 'Due'}: {formatCurrency(project.amountRemaining)}</span>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <p className="text-muted-foreground text-sm text-center py-8">{t('common.noResults')}</p>
            )}
          </CardContent>
        </Card>
      </div>
    );
  }

  // PRODUCT mode reports
  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <h1 className="text-2xl font-bold dark:text-white">{t('nav.reports')}</h1>
        <div className="flex flex-wrap gap-2">
          <div className="flex items-center gap-1 bg-muted rounded-lg p-1">
            <Button
              variant={period === 'day' ? 'default' : 'ghost'}
              size="sm"
              onClick={() => { setPeriod('day'); setCustomRange(null); }}
              className="text-xs"
            >
              {language === 'fr' ? 'Jour' : 'Day'}
            </Button>
            <Button
              variant={period === 'week' ? 'default' : 'ghost'}
              size="sm"
              onClick={() => { setPeriod('week'); setCustomRange(null); }}
              className="text-xs"
            >
              {language === 'fr' ? 'Semaine' : 'Week'}
            </Button>
            <Button
              variant={period === 'month' ? 'default' : 'ghost'}
              size="sm"
              onClick={() => { setPeriod('month'); setCustomRange(null); }}
              className="text-xs"
            >
              {language === 'fr' ? 'Mois' : 'Month'}
            </Button>
          </div>
          <Button variant="outline" size="sm" onClick={() => exportData('orders')}>
            <Download className="w-4 h-4 mr-1" /> {language === 'fr' ? 'Commandes' : 'Orders'}
          </Button>
          <Button variant="outline" size="sm" onClick={() => exportData('clients')}>
            <Download className="w-4 h-4 mr-1" /> Clients
          </Button>
          <Button variant="outline" size="sm" onClick={() => exportData('products')}>
            <Download className="w-4 h-4 mr-1" /> {language === 'fr' ? 'Produits' : 'Products'}
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <Card className="border-l-4 border-l-blue-500">
          <CardContent className="p-4 flex items-center gap-4">
            <div className="w-12 h-12 rounded-full bg-blue-100 dark:bg-blue-900/30 flex items-center justify-center">
              <DollarSign className="w-6 h-6 text-blue-600" />
            </div>
            <div>
              <p className="text-sm text-muted-foreground">{language === 'fr' ? 'Revenus (30j)' : 'Revenue (30d)'}</p>
              <p className="text-2xl font-bold dark:text-white">{formatCurrency(report?.totalRevenue || 0)}</p>
            </div>
          </CardContent>
        </Card>
        <Card className="border-l-4 border-l-amber-500">
          <CardContent className="p-4 flex items-center gap-4">
            <div className="w-12 h-12 rounded-full bg-amber-100 dark:bg-amber-600/20 flex items-center justify-center">
              <TrendingUp className="w-6 h-6 text-amber-500" />
            </div>
            <div>
              <p className="text-sm text-muted-foreground">{language === 'fr' ? 'B├⌐n├⌐fices (30j)' : 'Profit (30d)'}</p>
              <p className="text-2xl font-bold dark:text-white">{formatCurrency(report?.totalProfit || 0)}</p>
            </div>
          </CardContent>
        </Card>
        <Card className="border-l-4 border-l-emerald-500">
          <CardContent className="p-4 flex items-center gap-4">
            <div className="w-12 h-12 rounded-full bg-emerald-100 dark:bg-emerald-900/30 flex items-center justify-center">
              <ShoppingCart className="w-6 h-6 text-emerald-500" />
            </div>
            <div>
              <p className="text-sm text-muted-foreground">{language === 'fr' ? 'Commandes (30j)' : 'Orders (30d)'}</p>
              <p className="text-2xl font-bold dark:text-white">{report?.totalOrders || 0}</p>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Sales by period */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 dark:text-white">
            <BarChart3 className="w-5 h-5" /> {language === 'fr' ? 'Ventes par p├⌐riode' : 'Sales by period'}
          </CardTitle>
        </CardHeader>
        <CardContent>
          {report?.salesByPeriod.length ? (
            <div className="space-y-2">
              {report.salesByPeriod.map((period) => {
                const maxRevenue = Math.max(...report.salesByPeriod.map((p) => p.revenue));
                const width = maxRevenue > 0 ? (period.revenue / maxRevenue) * 100 : 0;
                return (
                  <div key={period.period} className="flex items-center gap-3">
                    <span className="text-xs text-muted-foreground w-20 shrink-0">{period.period}</span>
                    <div className="flex-1 bg-muted rounded-full h-6 overflow-hidden">
                      <div className="bg-blue-600 h-full rounded-full flex items-center justify-end px-2 transition-all" style={{ width: `${Math.max(width, 5)}%` }}>
                        <span className="text-white text-xs font-medium">{formatCurrency(period.revenue)}</span>
                      </div>
                    </div>
                    <span className="text-xs text-muted-foreground w-8 text-right">{period.orders}</span>
                  </div>
                );
              })}
            </div>
          ) : (
            <p className="text-muted-foreground text-sm text-center py-8">{t('common.noResults')}</p>
          )}
        </CardContent>
      </Card>

      {/* Top sellers */}
      {report?.topSellers && report.topSellers.length > 0 && (
        <Card>
          <CardHeader><CardTitle className="dark:text-white">{language === 'fr' ? 'Meilleures vendeuses/vendeurs' : 'Top sellers'}</CardTitle></CardHeader>
          <CardContent>
            <div className="space-y-3">
              {report.topSellers.map((seller, i) => (
                <div key={i} className="flex items-center justify-between p-3 bg-muted/50 rounded-lg">
                  <div className="flex items-center gap-3">
                    <span className="w-8 h-8 rounded-full bg-amber-100 dark:bg-amber-600/20 flex items-center justify-center text-sm font-bold text-amber-600">{i + 1}</span>
                    <span className="font-medium dark:text-white">{seller.name}</span>
                  </div>
                  <div className="text-right">
                    <p className="font-bold dark:text-white">{formatCurrency(seller.revenue)}</p>
                    <p className="text-xs text-muted-foreground">{seller.orders} {language === 'fr' ? 'commandes' : 'orders'}</p>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

